  window.SERVICE_CUSTOM_VIEWS = {
    "quality-review-copyediting": "<div class=\"quality-review-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.quality-review-copyediting.prereq\">\n      Prerequisite: Omni Copyediting. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-copyediting.p1\">\n      Our Quality Review - Copyediting service provides a final check to make sure your revised manuscript is sound before it goes into production—for a fraction of the price of your original edit.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-copyediting.p2\">\n      After you review and revise your edited manuscript, you may want an editor to check your work to ensure that you've done it correctly and haven't created new errors in the process.\n    </p>\n    <blockquote class=\"editorial-testimonial-quote\" style=\"margin: 22px 0; padding: 16px 22px; border-left: 4px solid #ad7d42; background: rgba(173, 125, 66, 0.05); border-radius: 0 8px 8px 0; font-style: italic; color: #333;\">\n      <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.quality-review-copyediting.quote\">\n        \"I am really impressed by [the editor's] incredible attention to detail, and I am just so grateful there are people like her who can subject my writing to such close critical analysis.\"\n      </p>\n      <footer style=\"font-style: normal; font-weight: 600; color: #78716c; font-size: 0.88rem;\" class=\"editable-field\" data-block-key=\"service.quality-review-copyediting.author\">\n        — Michelle Dixon, author of <em>The Disappearance of Lilya Bekirova</em>\n      </footer>\n    </blockquote>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-copyediting.p3\">\n      With the Quality Review, an editor will not only review the work you've done on the manuscript in response to the editing, but ensure that you've adequately addressed all of the queries and comments.\n    </p>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.quality-review-copyediting.note\">\n      *There is a 5,000-word minimum charge for all editing services.\n    </p>\n  </div>\n</div>",
    "quality-review-line-editing": "<div class=\"quality-review-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.quality-review-line-editing.prereq\">\n      Prerequisite: Omni Line Editing. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-line-editing.p1\">\n      Our Quality Review - Line Editing service provides a final check to make sure your revised manuscript is sound before it goes into production—for a fraction of the price of your original edit.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-line-editing.p2\">\n      After you review and revise your edited manuscript, you may want an editor to check your work to ensure that you've done it correctly and haven't created new errors in the process.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-line-editing.p3\">\n      With the Quality Review, an editor will not only review the work you've done on the manuscript in response to the editing, but ensure that you've adequately addressed all of the queries and comments.\n    </p>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.quality-review-line-editing.note\">\n      *There is a 5,000-word minimum charge for all editing services.\n    </p>\n  </div>\n</div>",
    "quality-review-content-editing": "<div class=\"quality-review-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.quality-review-content-editing.prereq\">\n      Prerequisite: Omni Content Editing. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-content-editing.p1\">\n      Our Quality Review - Content Editing service provides a final check to make sure your revised manuscript is sound before it goes into production—for a fraction of the price of your original edit.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-content-editing.p2\">\n      After you review and revise your edited manuscript, you may want an editor to check your work to ensure that you've done it correctly and haven't created new errors in the process.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-content-editing.p3\">\n      Content Editing, by its very nature, involves extensive revisions to your manuscript — for example, restructuring sentences and adding material. With the Quality Review, an editor will not only review the work you've done on the manuscript in response to the editing, but ensure that you've adequately addressed all of the queries and comments.\n    </p>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.quality-review-content-editing.note\">\n      *There is a 5,000-word minimum charge for all editing services.\n    </p>\n  </div>\n</div>",
    "quality-review-content-editing-plus": "<div class=\"quality-review-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.quality-review-content-editing-plus.prereq\">\n      Prerequisite: Omni Content Editing Plus. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-content-editing-plus.p1\">\n      Our Quality Review - Content Editing Plus service provides a final check to make sure your revised manuscript is sound before it goes into production—for a fraction of the price of your original edit.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-content-editing-plus.p2\">\n      After you review and revise your edited manuscript, you may want an editor to check your work to ensure that you've done it correctly and haven't created new errors in the process.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-content-editing-plus.p3\">\n      Content Editing, by its very nature, involves extensive revisions to your manuscript — for example, restructuring sentences and adding material. With the Quality Review, an editor will not only review the work you've done on the manuscript in response to the editing, but ensure that you've adequately addressed all of the queries and comments.\n    </p>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.quality-review-content-editing-plus.note\">\n      *There is a 5,000-word minimum charge for all editing services.\n    </p>\n  </div>\n</div>",
    "editorial-assistant-copyediting": "<div class=\"editorial-assistant-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.editorial-assistant-copyediting.prereq\">\n      Prerequisite: Omni Copyediting. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-copyediting.p1\">\n      Your editorial assistant will review each change and suggestion given during the Copyediting service and take action on each one.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-copyediting.p2\">\n      Going through an edited manuscript can sometimes be a time-consuming process for even the most experienced author, as it requires decisions be made regarding each of the revisions, comments, and recommendations. For our busiest authors and for authors who may be unsure of their own ability to make the needed changes, Omni offers the Editorial Assistant service, in which a professional editor handles the editing work for the author.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-copyediting.p3\">\n      Your editorial assistant will review each change and suggestion given during the copyediting and take action on each one, accepting changes, rewriting sentences, resolving queries and handling other revisions suggested by the original copyeditor. This service is ideal for authors who approve of most of the editor's work on their manuscript and do not wish to work with tracked changes in their manuscript.\n    </p>\n    <p class=\"mb-3 fw-medium editable-field\" style=\"color: #2b2219;\" data-block-key=\"service.editorial-assistant-copyediting.cost\">\n      Estimate of cost is provided with your completed Copyedit.\n    </p>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.editorial-assistant-copyediting.note\">\n      Please note: There may be some questions or comments from the editor that you, the author, will need to address before moving forward with this service.\n    </p>\n  </div>\n</div>",
    "editorial-assistant-line-edit": "<div class=\"editorial-assistant-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.editorial-assistant-line-edit.prereq\">\n      Prerequisite: Omni Line Edit. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-line-edit.p1\">\n      Your editorial assistant will review each change and suggestion given during the Line Edit service and take action on each one.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-line-edit.p2\">\n      Going through an edited manuscript can sometimes be a time-consuming process for even the most experienced author, as it requires decisions be made regarding each of the revisions, comments, and recommendations. For our busiest authors and for authors who may be unsure of their own ability to make the needed changes, Omni offers the Editorial Assistant service, in which a professional editor handles the editing work for the author.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-line-edit.p3\">\n      Your editorial assistant will review each change and suggestion given during the line edit and take action on each one, accepting changes, rewriting sentences, resolving queries and handling other revisions as suggested by the line editor. This service is ideal for authors who approve of most of the editor's work on their manuscript and do not wish to work with tracked changes in their manuscript.\n    </p>\n    <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n      <p class=\"mb-1 editable-field\" data-block-key=\"service.editorial-assistant-line-edit.duration\"><strong style=\"color: #ad7d42;\">Duration: </strong> 2-3 weeks</p>\n      <p class=\"mb-0 editable-field\" data-block-key=\"service.editorial-assistant-line-edit.cost\"><strong style=\"color: #ad7d42;\">Cost: </strong> Estimate provided with your completed Line Edit.</p>\n    </div>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.editorial-assistant-line-edit.note\">\n      Please note: There may be some questions or comments from the editor that you, the author, will need to address before moving forward with this service.\n    </p>\n  </div>\n</div>",
    "editorial-assistant-content-edit": "<div class=\"editorial-assistant-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.editorial-assistant-content-edit.prereq\">\n      Prerequisite: Omni Content Edit. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-content-edit.p1\">\n      Your editorial assistant will review each change and suggestion given during the Content Edit service and take action on each one.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-content-edit.p2\">\n      Going through an edited manuscript can sometimes be a time-consuming process for even the most experienced author, as it requires decisions be made regarding each of the revisions, comments, and recommendations. For our busiest authors and for authors who may be unsure of their own ability to make the needed changes, Omni offers the Editorial Assistant service, in which a professional editor handles the editing work for the author.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-content-edit.p3\">\n      Your editorial assistant will review each change and suggestion given during the Content Edit and take action on each one, accepting changes, rewriting sentences, resolving queries and handling other revisions as suggested by the content editor. This service is ideal for authors who approve of most of the editor's work on their manuscript and do not wish to work with tracked changes in their manuscript.\n    </p>\n    <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n      <p class=\"mb-1 editable-field\" data-block-key=\"service.editorial-assistant-content-edit.duration\"><strong style=\"color: #ad7d42;\">Duration: </strong> 2-3 weeks</p>\n      <p class=\"mb-0 editable-field\" data-block-key=\"service.editorial-assistant-content-edit.cost\"><strong style=\"color: #ad7d42;\">Cost: </strong> Estimate provided with your completed content edit.</p>\n    </div>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.editorial-assistant-content-edit.note\">\n      Please note: There may be some questions or comments from the editor that you, the author, will need to address before moving forward with this service.\n    </p>\n  </div>\n</div>",
    "editorial-assistant-content-edit-plus": "<div class=\"editorial-assistant-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.editorial-assistant-content-edit-plus.prereq\">\n      Prerequisite: Omni Content Edit Plus. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-content-edit-plus.p1\">\n      Your editorial assistant will review each change and suggestion given during the Content Edit Plus service and take action on each one.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-content-edit-plus.p2\">\n      Going through an edited manuscript can sometimes be a time-consuming process for even the most experienced author, as it requires decisions be made regarding each of the revisions, comments, and recommendations. For our busiest authors and for authors who may be unsure of their own ability to make the needed changes, Omni offers the Editorial Assistant service, in which a professional editor handles the editing work for the author.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-content-edit-plus.p3\">\n      Your editorial assistant will review each change and suggestion given during the Content Editor Plus service and take action on each one, accepting changes, rewriting sentences, resolving queries ,and handling other revisions as suggested by the Content Editor Plus service. This service is ideal for authors who approve of most of the editor's work on their manuscript and do not wish to work with tracked changes in their manuscript.\n    </p>\n    <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n      <p class=\"mb-1 editable-field\" data-block-key=\"service.editorial-assistant-content-edit-plus.duration\"><strong style=\"color: #ad7d42;\">Duration: </strong> 2-3 weeks</p>\n      <p class=\"mb-0 editable-field\" data-block-key=\"service.editorial-assistant-content-edit-plus.cost\"><strong style=\"color: #ad7d42;\">Cost: </strong> Estimate provided with your completed content edit plus.</p>\n    </div>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.editorial-assistant-content-edit-plus.note\">\n      Please note: There may be some questions or comments from the editor that you, the author, will need to address before moving forward with this service.\n    </p>\n  </div>\n</div>",
    "cover-copy-polish": "<div class=\"cover-copy-polish-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.cover-copy-polish.p1\">\n      With Omni Cover Copy Polishing, the ideas you provide will allow us to create intriguing copy that can help you clinch the sale. Our professional copywriting staff will mold the text that you provide into marketable material by polishing the hardcover flaps, back cover copy, author bio and keynote, in addition to any other cover material you have submitted.\n    </p>\n    <p class=\"mb-0 editable-field\" data-block-key=\"service.cover-copy-polish.p2\">\n      Create intriguing cover text and catch the attention of book buyers with this professional copywriting service. The typical timeline for this service is <strong>one week</strong>, depending on our queue and the complexity of your work.\n    </p>\n  </div>\n</div>",

  "evaluation-services": "<div class=\"evaluation-services-overview-content\">\n                      \n                      <div class=\"evaluation-section-block mb-4\">\n                        <h4 \n                          class=\"editorial-accent-title fw-bold mb-2 editable-field\" \n                          style=\"color: #d9534f; font-size: 1.25rem;\"\n                          data-block-key=\"service.evaluation-services.rx_title\"\n                         data-block-key=\"service.evaluation-services.h4_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('evaluation-services', this)\">\n                          <span class=\"editable-field\" data-block-key=\"service.evaluation-services.rx_title\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.evaluation-services.rx_title', this.innerText.trim())\">Editorial Rx Referral</span>\n                        </h4>\n                        <p \n                          class=\"editorial-section-p mb-3 editable-field\" \n                          style=\"color: #57534e; font-size: 0.98rem; line-height: 1.7;\"\n                          data-block-key=\"service.evaluation-services.rx_desc\"\n                         data-block-key=\"service.evaluation-services.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('evaluation-services', this)\">\n                          <span class=\"editable-field\" data-block-key=\"service.evaluation-services.rx_desc\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.evaluation-services.rx_desc', this.innerText.trim())\">Through this service, an evaluator will recommend the services of an appropriate editorial specialist—from a copyeditor or content editor to a developmental editor or book doctor.</span>\n                        </p>\n                        \n                        \n                        <blockquote \n                          class=\"editorial-testimonial-quote\"\n                          style=\"margin: 18px 0; padding: 16px 20px; border-left: 4px solid #d9534f; background: rgba(217; border-radius: 0 8px 8px 0; font-style: italic; color: #444;\"\n                        >\n                          <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.evaluation-services.rx_quote\" data-block-key=\"service.evaluation-services.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('evaluation-services', this)\">\n                            <span class=\"editable-field\" data-block-key=\"service.evaluation-services.rx_quote\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.evaluation-services.rx_quote', this.innerText.trim())\">\"With the various points to examine and adjust in mind, I re-read This Golden Land and made changes along the way. These were excellent points, by the way, and very helpful to me for cleaning up the manuscript.\"</span>\n                          </p>\n                          <footer \n                            class=\"editorial-quote-author\" \n                            style=\"font-style: normal; font-weight: 600; color: #666; font-size: 0.88rem;\"\n                            data-block-key=\"service.evaluation-services.rx_author\"\n                          >\n                            <span class=\"editable-field\" data-block-key=\"service.evaluation-services.rx_author\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.evaluation-services.rx_author', this.innerText.trim())\">-Barbara Wood, author of This Golden Land</span>\n                          </footer>\n                        </blockquote>\n                      </div>\n\n                      \n                      <div class=\"evaluation-section-block mb-4\">\n                        <h4 \n                          class=\"editorial-accent-title fw-bold mb-2 editable-field\" \n                          style=\"color: #d9534f; font-size: 1.25rem;\"\n                          data-block-key=\"service.evaluation-services.eval_title\"\n                         data-block-key=\"service.evaluation-services.h4_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('evaluation-services', this)\">\n                          <span class=\"editable-field\" data-block-key=\"service.evaluation-services.eval_title\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.evaluation-services.eval_title', this.innerText.trim())\">Editorial Evaluation Services</span>\n                        </h4>\n                        <p \n                          class=\"editorial-section-p mb-0 editable-field\" \n                          style=\"color: #57534e; font-size: 0.98rem; line-height: 1.7;\"\n                          data-block-key=\"service.evaluation-services.eval_desc\"\n                         data-block-key=\"service.evaluation-services.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('evaluation-services', this)\">\n                          <span class=\"editable-field\" data-block-key=\"service.evaluation-services.eval_desc\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.evaluation-services.eval_desc', this.innerText.trim())\">Regardless of your publishing goals, the editorial quality of your work matters—no one wants to read a book that's riddled with typos and grammatical errors. However, even the best writers make occasional mistakes. Omni provides editorial services that will help you make your book the best it can be.</span>\n                        </p>\n                      </div>\n\n                      \n                      <div class=\"publishing-packages-container mt-4\">\n                        <div \n                          class=\"publishing-package-card\"\n                          onclick=\"selectServiceBySlug(\'editorial-evaluation\')\"\n                          style=\"cursor: pointer;\"\n                        >\n                          <div class=\"publishing-package-card-header\">\n                            <h5 class=\"publishing-package-card-title m-0 editable-field\" data-block-key=\"service.evaluation-services.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('evaluation-services', this)\">\n                              Editorial Evaluation\n                            </h5>\n                            <span class=\"publishing-package-arrow-badge\">\n                              <i class=\"bi bi-arrow-right-short\"></i>\n                            </span>\n                          </div>\n                          <p class=\"publishing-package-card-summary editable-field\" data-block-key=\"service.evaluation-services.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('evaluation-services', this)\">\n                            Explore our complete manuscript diagnostic checkup, detailed observations report, and $299 credit toward professional editorial services.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "editorial-evaluation": "<div class=\"editorial-evaluation-detail-content\">\n                      \n                      <div class=\"editorial-evaluation-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-evaluation.p1\" data-block-key=\"service.editorial-evaluation.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('editorial-evaluation', this)\">\n                          <span class=\"editable-field\" data-block-key=\"service.editorial-evaluation.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.editorial-evaluation.p1', this.innerText.trim())\">The Editorial Evaluation is a manuscript checkup that assesses your work to be sure that it has fulfilled the basic requirements of a published book. The editorial evaluator will not only provide you with a general overview of your manuscript but will also educate you through constructive comments on how to write a better book.</span>\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-evaluation.p2\" data-block-key=\"service.editorial-evaluation.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('editorial-evaluation', this)\">\n                          <span class=\"editable-field\" data-block-key=\"service.editorial-evaluation.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.editorial-evaluation.p2', this.innerText.trim())\">The Editorial Evaluation is a detailed report on the observations of an evaluator about the strengths and weaknesses of your manuscript (rather than an editing of your manuscript). At the end of the evaluation, an Editorial Rx Referral will recommend the services of an appropriate editorial specialist—from a copyeditor or content editor to a developmental editor. You may then choose to purchase those services from Omni. If you do choose to purchase an editorial service, our staff will assign your book to a specialist who will address the issues raised in the Editorial Evaluation and give your manuscript the professional attention that it would receive at a traditional publishing house. You may also choose to use your own freelance editor or make the recommended changes yourself.</span>\n                        </p>\n\n                        \n                        <blockquote \n                          class=\"editorial-testimonial-quote\"\n                          style=\"margin: 22px 0; padding: 16px 22px; border-left: 4px solid #ad7d42; background: rgba(173; border-radius: 0 8px 8px 0; font-style: italic; color: #333;\"\n                        >\n                          <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.editorial-evaluation.quote\" data-block-key=\"service.editorial-evaluation.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('editorial-evaluation', this)\">\n                            <span class=\"editable-field\" data-block-key=\"service.editorial-evaluation.quote\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.editorial-evaluation.quote', this.innerText.trim())\">\"I appreciate all the editorial work that went into the analysis – I was very impressed with the job Omni did with my book. The analysis was thorough, clear, and very helpful. Thank you again for all your assistance on making his Golden LandT even better!\"</span>\n                          </p>\n                          <footer \n                            class=\"editorial-quote-author\" \n                            style=\"font-style: normal; font-weight: 600; color: #78716c; font-size: 0.88rem;\"\n                            data-block-key=\"service.editorial-evaluation.quote_author\"\n                          >\n                            <span class=\"editable-field\" data-block-key=\"service.editorial-evaluation.quote_author\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.editorial-evaluation.quote_author', this.innerText.trim())\">—Barbara Wood, author of This Golden Land</span>\n                          </footer>\n                        </blockquote>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-evaluation.p3\" data-block-key=\"service.editorial-evaluation.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('editorial-evaluation', this)\">\n                          <span class=\"editable-field\" data-block-key=\"service.editorial-evaluation.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.editorial-evaluation.p3', this.innerText.trim())\">The Editorial Evaluation also qualifies you for possible selection to our prestigious Editor's Choice program.</span>\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-evaluation.p4\" data-block-key=\"service.editorial-evaluation.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('editorial-evaluation', this)\">\n                          <span class=\"editable-field\" data-block-key=\"service.editorial-evaluation.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.editorial-evaluation.p4', this.innerText.trim())\">Here are a few examples of questions that are answered in Editorial Evaluations depending on your book's genre.</span>\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-evaluation.p5\" data-block-key=\"service.editorial-evaluation.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('editorial-evaluation', this)\">\n                          <span class=\"editable-field\" data-block-key=\"service.editorial-evaluation.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.editorial-evaluation.p5', this.innerText.trim())\">Please note: The Editorial Evaluation is not a replacement for Omni's editorial services. Rather, it is a preliminary diagnostic tool, examining several sections of the manuscript in detail, to pinpoint areas in need of improvement. Evaluators offer examples of items that could be strengthened and give critique and commentary across a range of topics.</span>\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.editorial-evaluation.p6\" data-block-key=\"service.editorial-evaluation.p7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('editorial-evaluation', this)\">\n                          <span class=\"editable-field\" data-block-key=\"service.editorial-evaluation.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.editorial-evaluation.p6', this.innerText.trim())\">The Editorial Evaluation fee is based on industry standard manuscript word count of 100,000 words or less. For manuscripts above 100,000 words, the author may choose to have approximately the first 100,000 words assessed during the Editorial Evaluation. If the author wishes to have the full manuscript evaluated, an additional fee for each 50,000 words over 100,000 will be required. Should the author purchase one of our editing services, the full manuscript will be edited line by line.</span>\n                        </p>\n                      </div>\n\n                      \n                      <div \n                        class=\"editorial-note-callout p-3 mb-4 rounded-3\"\n                        style=\"background: #faf6f0; border: 1px solid rgba(173; border-left: 5px solid #ad7d42;\"\n                      >\n                        <div class=\"fw-bold mb-1\" style=\"color: #2b2219; font-size: 0.95rem;\">Note:</div>\n                        <p class=\"fst-italic mb-2 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.6;\" data-block-key=\"service.editorial-evaluation.credit_note\" data-block-key=\"service.editorial-evaluation.p8\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('editorial-evaluation', this)\">\n                          <span class=\"editable-field\" data-block-key=\"service.editorial-evaluation.credit_note\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.editorial-evaluation.credit_note', this.innerText.trim())\">You have the option to work with your editor or make changes yourself. However, should you decide to purchase any of our Editorial Services, you will receive a $299 credit which will be deducted from the overall editing cost.</span>\n                        </p>\n                        <div class=\"fw-bold\" style=\"color: #ad7d42; font-size: 0.92rem;\" data-block-key=\"service.editorial-evaluation.duration\">\n                          <span class=\"editable-field\" data-block-key=\"service.editorial-evaluation.duration\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleHeaderSave('service.editorial-evaluation.duration', this.innerText.trim())\">Duration: 2-3 Weeks</span>\n                        </div>\n                      </div>\n                    </div>",
  "developmental-editing": "<div class=\"developmental-editing-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-1 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.developmental-editing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                          Prescribed by Editorial Evaluation only. Please speak with your editorial consultant for more information.\n                        </p>\n                        <p class=\"fst-italic mb-0 fw-semibold editable-field\" style=\"color: #ad7d42; font-size: 0.92rem;\" data-block-key=\"service.developmental-editing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                          Please Note: A Developmental Edit includes FREE Content Editing and Quality Review.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.developmental-editing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                          The Omni Developmental Editing service combines three editorial services into one package: First, a developmental editor evaluates the manuscript at the paragraph, chapter, and book levels and makes suggestions throughout the manuscript to identify big-picture areas that need work.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fcfbf9; border: 1px solid #ebd9c4;\">\n                          <ul class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.94rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.developmental-editing.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                              <strong>For fiction works</strong>, the editor will analyze the readership and genre to determine whether the content is appropriate. He will then examine essential considerations such as plot, pace, characterization and dialogue.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.developmental-editing.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                              <strong>For nonfiction titles</strong>, the editor will analyze the readership, purpose, and possible uses of the work to determine that the content is complete and appropriate; that concepts are developed adequately; that material is well organized; and that illustrations, tables, and lists are used effectively throughout.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.developmental-editing.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                          Authors can choose to make improvements suggested by the developmental editor themselves or purchase the services of a Book Doctor to help them make alterations. (If applicable, a price estimate for book doctoring is included with the completed developmental edit.) Once big-picture changes have been made, the second step, a free Content Edit, begins; the content editor will check the manuscript for errors in grammar, spelling, and punctuation. And third, the manuscript will receive a quality review to ensure the manuscript is editorially sound before it goes into production.\n                        </p>\n\n                        <blockquote \n                          class=\"editorial-testimonial-quote\"\n                          style=\"margin: 22px 0; padding: 16px 22px; border-left: 4px solid #ad7d42; background: rgba(173; border-radius: 0 8px 8px 0; font-style: italic; color: #333;\"\n                        >\n                          <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.developmental-editing.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                            \"I am THRILLED with the edit so far! I've never had a developmental edit, and it's so cool to 'hear' someone else's voice regarding the material. What's more, the editor has targeted areas that I subconsciously knew needed work, but just didn't hear my conscious voice telling me how to correct. Please let her know how excited I am and how far her input had surpassed what I thought I was paying for.\"\n                          </p>\n                          <footer style=\"font-style: normal; font-weight: 600; color: #78716c; font-size: 0.88rem;\">\n                            — Eric Rankin, author of <em>The Aquarians</em>\n                          </footer>\n                        </blockquote>\n                      </div>\n                    </div>",
  "book-doctor": "<div class=\"book-doctor-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.book-doctor.prereq\">\n      Prerequisite: Omni Developmental Edit. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.book-doctor.p1\">\n      Following the advice of a professional editor takes time and careful consideration. Developmental Editing, in particular, often requires the author to rewrite or reorganize the manuscript to enhance material. Hiring a book doctor may be the best choice for authors who don't have the time or ability to make the big-picture changes recommended by a developmental editor.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.book-doctor.p2\">\n      A book doctor makes the changes recommended by the developmental editor and approved by the author. A price quote for the book doctor will be provided with the completed developmental edit.\n    </p>\n    <p class=\"mb-3 fw-medium editable-field\" style=\"color: #2b2219;\" data-block-key=\"service.book-doctor.p3\">\n      After completion of Book Doctoring, Content Editing and a Quality Review will be provided at no extra cost.\n    </p>\n    <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n      <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n      <span style=\"color: #57534e;\">Estimate based on work required and detailed through the Developmental Edit.</span>\n    </div>\n  </div>\n</div>",
  "small-book-review-with-editing-under-5-000-words": "<div class=\"small-book-review-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                          We know you’ve put a lot of energy and dedication into your manuscript, but even experienced authors overlook their own mistakes sometimes. Since the editorial quality of your book will have an impact on your readers and its ultimate success, it’s important to have another set of professional eyes look over your book before it’s published.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                          The Omni editors carefully review your full manuscript (under 5,000 words) and provide you with the edits best suited to your book. This all-inclusive service is an excellent option for children’s books. We won’t just point out what’s not working; we can help you decide exactly how to fix it.\n                        </p>\n\n                        <p class=\"fw-semibold mb-2 editable-field\" style=\"color: #2b2219;\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                          Here’s what to expect:\n                        </p>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                            <strong>Line Editing: </strong>We perfect your spelling, punctuation, capitalization, grammar, and syntax. And we’ll provide recommendations for word choice and improving overall readability.\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                            <strong>Content Editing: </strong>We confirm the consistency of information and ideas throughout the whole book, and we also focus on more extensive sentence restructuring.\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                            Our editors use Microsoft Word® to track their changes, so you always <strong>retain control over final edits.</strong>\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                            Our editors typically turn your manuscript around in <strong>three to four weeks.</strong> After that time, your editor will reach out with their edits and suggestions for improvement.\n                          </li>\n                        </ul>\n\n                        <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"fst-italic mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                            <strong>Please Note: </strong>This service does not include our advanced editorial services, such as Developmental Editing. Rather, it is a combination of our Line Editing and Content Editing services with a report from the editor.\n                          </p>\n                        </div>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.1rem;\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                          More About | Small Book Review with Editing (Under 5,000 Words)\n                        </h5>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                          Almost nothing compares to publishing a book that is polished and clear. Choose to make your book the best it can be with our combined review and editing service. The typical timeline for this service is <strong>three to four weeks</strong>, depending on the work queue and the complexity of your manuscript. Call <strong>1-800-AUTHORS (288-4677)</strong> for more information, or to purchase this service.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"fst-italic fw-medium mb-2 editable-field\" style=\"color: #78716c; font-size: 0.92rem;\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                            *Please note:\n                          </p>\n                          <ul class=\"mb-0 ps-3 d-flex flex-column gap-2 fst-italic\" style=\"color: #57534e; font-size: 0.9rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                              Omni accepts a very low margin of error in each completed edit. Our professional in-house editorial staff reviews each editorial service for quality assurance – an edit won’t be returned to an author until fewer than three percent of the original errors remain.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                              Upon reviewing your edited manuscript, if you believe that an unsatisfactory number of errors have been addressed, please create a list of the errors and the page numbers on which they appear and email it to <a href=\"mailto:editorial@omnivirtualsolution.com\" style=\"color: #ad7d42; text-decoration: underline;\">editorial@omnivirtualsolution.com</a>. We will review the list with you and address your concern.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "copyediting": "<div class=\"copyediting-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.copyediting.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('copyediting', this)\">\n                          Prescribed by Editorial Evaluation only. Please do not order without first speaking with your editorial consultant.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.copyediting.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('copyediting', this)\">\n                          An experienced copyeditor will check your manuscript carefully, correcting errors in spelling, grammar, and punctuation. In addition, the copyeditor will verify cross-references and impose an industry-standard style.\n                        </p>\n\n                        <blockquote \n                          class=\"editorial-testimonial-quote\"\n                          style=\"margin: 22px 0; padding: 16px 22px; border-left: 4px solid #ad7d42; background: rgba(173; border-radius: 0 8px 8px 0; font-style: italic; color: #333;\"\n                        >\n                          <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.copyediting.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('copyediting', this)\">\n                            \"I took my editorial consultant's comment to heart that regardless of the quality of the book's content and message, grammatical errors will cause the public to lose respect for it. As a structural engineer, I can appreciate that since I regularly submit documents and have them submitted to me. The presentation is as important as the content. The editor's contribution has greatly enhanced my manuscript and was well worth the cost. I would recommend the use of an editor to any serious author.\"\n                          </p>\n                          <footer style=\"font-style: normal; font-weight: 600; color: #78716c; font-size: 0.88rem;\">\n                            - Bill Stahl, author of <em>The Bible's Story of Salvation</em>\n                          </footer>\n                        </blockquote>\n\n                        <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.copyediting.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('copyediting', this)\">\n                          *There is a 5,000-word minimum charge for all editing services.\n                        </p>\n                      </div>\n                    </div>",
  "line-editing": "<div class=\"line-editing-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.line-editing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('line-editing', this)\">\n                          Some manuscripts simply require more work than others. When heavy copyediting is required, an editor will check the manuscript for more pervasive errors in spelling, grammar, and punctuation. The editor will also address syntax and word choice and make light recommendations for improving the overall readability of the work.\n                        </p>\n\n                        <blockquote \n                          class=\"editorial-testimonial-quote\"\n                          style=\"margin: 22px 0; padding: 16px 22px; border-left: 4px solid #ad7d42; background: rgba(173; border-radius: 0 8px 8px 0; font-style: italic; color: #333;\"\n                        >\n                          <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.line-editing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('line-editing', this)\">\n                            \"I would like to thank the editor for a heroic job. My mother was apprehensive ... her book is intended to convey the thoughts of a child. The quirky language reflects this, and she was afraid the child's \\\"voice\\\" might be lost in the editing. I read the first few chapters of the edited manuscript to her. She was delighted! It is clear that this is a very conscientious editor and one to be trusted.\"\n                          </p>\n                          <footer style=\"font-style: normal; font-weight: 600; color: #78716c; font-size: 0.88rem;\">\n                            Virginia Merrill, author of <em>Believe in Guardian Angels</em>\n                          </footer>\n                        </blockquote>\n\n                        <p class=\"fst-italic mb-2 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.line-editing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('line-editing', this)\">\n                          * Note: Line Editing is also available in Spanish. For more information, speak with your publishing consultant.\n                        </p>\n\n                        <p class=\"fst-italic mb-3 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.line-editing.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('line-editing', this)\">\n                          *There is a 5,000-word minimum charge for all editing services.\n                        </p>\n\n                        <p class=\"mb-4 editable-field\" style=\"font-size: 0.95rem;\" data-block-key=\"service.line-editing.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('line-editing', this)\">\n                          Leave it to our editorial specialists to take your book to the next level. The typical timeline for this service is <strong>six to eight weeks</strong>, depending on our queue and the complexity of your work.\n                        </p>\n\n                        <p class=\"fst-italic text-muted mb-0 editable-field\" style=\"font-size: 0.82rem; line-height: 1.6;\" data-block-key=\"service.line-editing.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('line-editing', this)\">\n                          Disclaimer: Prices listed do not include applicable taxes (such as sales, use, excise, value-added, goods and services, or other tax), which will be added to the total at the time of purchase. Prices listed do include the copies of the book; the cost of shipping and handling will be calculated and charged after your book is made available for sale.\n                        </p>\n                      </div>\n                    </div>",
  "content-editing": "<div class=\"content-editing-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.content-editing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing', this)\">\n                          Prescribed by Editorial Evaluation only. Please do not order without first speaking with your editorial consultant.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.content-editing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing', this)\">\n                          In addition to performing the functions of a line edit, a content editor will work to ensure the general accuracy and consistency of content and focus on more extensive restructuring of sentences.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fcfbf9; border: 1px solid #ebd9c4;\">\n                          <ul class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.94rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.content-editing.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing', this)\">\n                              <strong>For fiction titles, </strong>the editor will focus on maintaining consistency of details in the plot, characters and setting.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.content-editing.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing', this)\">\n                              <strong>For nonfiction titles, </strong>the editor will monitor consistency of information and ideas.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <p class=\"fst-italic mb-3 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.content-editing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing', this)\">\n                          *There is a 5,000-word minimum charge for all editing services.\n                        </p>\n\n                        <p class=\"mb-0 editable-field\" style=\"font-size: 0.95rem;\" data-block-key=\"service.content-editing.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing', this)\">\n                          Leave it to our editorial specialists to take your book to the next level. The typical timeline for this service is <strong>six to eight weeks</strong>, depending on our queue and the complexity of your work.\n                        </p>\n                      </div>\n                    </div>",
  "content-editing-plus": "<div class=\"content-editing-plus-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.content-editing-plus.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                          Prescribed by Editorial Evaluation only. Please do not order without first speaking with your editorial consultant.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.content-editing-plus.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                          This service is ideal for manuscripts that need more work on sentence structure and grammar than basic Content Editing can provide. Content Editing Plus is especially suitable for translations or manuscripts written by authors whose second language is English.\n                        </p>\n\n                        <blockquote \n                          class=\"editorial-testimonial-quote\"\n                          style=\"margin: 22px 0; padding: 16px 22px; border-left: 4px solid #ad7d42; background: rgba(173; border-radius: 0 8px 8px 0; font-style: italic; color: #333;\"\n                        >\n                          <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.content-editing-plus.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                            \"It is difficult to imagine the best editor at HarperCollins doing a better job than my Omni editor. Editing services through Omni are equal to the finest brick and mortar publishing houses and far more timely.\"\n                          </p>\n                          <footer style=\"font-style: normal; font-weight: 600; color: #78716c; font-size: 0.88rem;\">\n                            -Michael R Zomber, author of <em>Shogun Iemitsu</em>\n                          </footer>\n                        </blockquote>\n\n                        <p class=\"fst-italic mb-3 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.content-editing-plus.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                          *There is a 5,000-word minimum charge for all editing services.\n                        </p>\n\n                        <p class=\"mb-0 editable-field\" style=\"font-size: 0.95rem;\" data-block-key=\"service.content-editing-plus.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                          Leave it to our editorial specialists to take your book to the next level. The typical timeline for this service is <strong>six to eight weeks</strong>, depending on our queue and the complexity of your work.\n                        </p>\n                      </div>\n                    </div>\n                  ) : (selectedService?.slug === 'cover-copy-polish' && !isCurrentSubcategoryOverview) ? (\n                    \n                    <div class=\"cover-copy-polish-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.content-editing-plus.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                          With Omni Cover Copy Polishing, the ideas you provide will allow us to create intriguing copy that can help you clinch the sale. Our professional copywriting staff will mold the text that you provide into marketable material by polishing the hardcover flaps, back cover copy, author bio and keynote, in addition to any other cover material you have submitted.\n                        </p>\n\n                        <p class=\"mb-0 editable-field\" data-block-key=\"service.content-editing-plus.p7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                          Create intriguing cover text and catch the attention of book buyers with this professional copywriting service. The typical timeline for this service is <strong>one week</strong>, depending on our queue and the complexity of your work.\n                        </p>\n                      </div>\n                    </div>",
  "professional-indexing": "<div class=\"professional-indexing-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.professional-indexing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          Please speak with your editorial consultant for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.professional-indexing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          Our professional indexers will provide you with an industry-standard, two-level topical index that is personalized to provide maximum usability for the book's target audience.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.professional-indexing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          The professional indexer analyzes your entire book, anticipating line items your reader will most likely want to find and listing them in an intuitive, accessible manner.\n                        </p>\n                        <p class=\"mb-2 editable-field\" data-block-key=\"service.professional-indexing.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          Before handcrafting your one-of-a-kind index, our professional indexer considers the following four elements that make your book unique:\n                        </p>\n\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-1\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.professional-indexing.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">Focus</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-indexing.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">Purpose</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-indexing.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">Audience</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-indexing.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">Organization</li>\n                        </ul>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.professional-indexing.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          The resulting high-quality index is the standard found throughout the publishing industry.\n                        </p>\n\n                        <p class=\"fst-italic mb-3 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.professional-indexing.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          *There is a 5,000-word minimum charge for all editing services.\n                        </p>\n\n                        <p class=\"fst-italic text-muted mb-0 editable-field\" style=\"font-size: 0.9rem; line-height: 1.65;\" data-block-key=\"service.professional-indexing.p7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          Please note: We craft indexes from the final, formatted, author-approved pages. Changes made after indexing may alter the pagination and detract from the index's usability or may lead to additional charges to correct the index.\n                        </p>\n                      </div>\n                    </div>",
  "computer-generated-keyword-indexing-up-to-500-entries": "<div class=\"keyword-indexing-500-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-500-entries.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-500-entries', this)\">\n                          A computer-generated keyword index lists a page number for a key term each time it occurs in the book. You simply provide Omni with a list of words that you want to appear in the index. Omni will create an index by tagging the selected words during the production process. The resulting alphabetical list of keywords gives the page numbers for each occurrence of the word.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-500-entries.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-500-entries', this)\">\n                          The success of this type of index depends entirely on the key words you chose. The choice of words needs to be carefully thought through. Do not use simple words or words that repeat constantly throughout the text. For example, if you are writing a cookbook, do not index the word egg. Every time the word \"egg\" is mentioned, the computer will index that page. We presume that egg would show up on many recipe pages. If words are not chosen carefully, the resulting index can be overly long and unusable.\n                        </p>\n\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-500-entries.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-500-entries', this)\">\n                          Please note: a concordance-type index has no logical organization other than alphabetization, and only exact word matches can be indexed using the approach.\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" style=\"font-size: 0.93rem; line-height: 1.68;\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-500-entries.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-500-entries', this)\">\n                          *We highly recommend our Professional Index service if you require an industry-standard index. A computer cannot do what a professional, human indexer can—evaluate the significance of each occurrence of a word and whether it's really important to list, develop appropriate cross references and sub-entries, phrase entries in the most useful way, and more.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timing: </span>\n                          <span style=\"color: #57534e;\">Adds two weeks to the design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "computer-generated-keyword-indexing-up-to-700-entries": "<div class=\"keyword-indexing-700-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-700-entries.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-700-entries', this)\">\n                          A computer-generated keyword index lists a page number for a key term each time it occurs in the book. You simply provide Omni with a list of words that you want to appear in the index. Omni will create an index by tagging the selected words during the production process. The resulting alphabetical list of keywords gives the page numbers for each occurrence of the word.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-700-entries.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-700-entries', this)\">\n                          The success of this type of index depends entirely on the key words you chose. The choice of words needs to be carefully thought through. Do not use simple words or words that repeat constantly throughout the text. For example, if you are writing a cookbook, do not index the word egg. Every time the word \"egg\" is mentioned, the computer will index that page. We presume that egg would show up on many recipe pages. If words are not chosen carefully, the resulting index can be overly long and unusable.\n                        </p>\n\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-700-entries.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-700-entries', this)\">\n                          Please note: a concordance-type index has no logical organization other than alphabetization, and only exact word matches can be indexed using the approach.\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" style=\"font-size: 0.93rem; line-height: 1.68;\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-700-entries.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-700-entries', this)\">\n                          *We highly recommend our Professional Index service if you require an industry-standard index. A computer cannot do what a professional, human indexer can—evaluate the significance of each occurrence of a word and whether it's really important to list, develop appropriate cross references and sub-entries, phrase entries in the most useful way, and more. Librarians and reviewers consider a computer-generated word list not simply less useful but a liability to a book.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timing: </span>\n                          <span style=\"color: #57534e;\">Adds two weeks to the design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "computer-generated-keyword-indexing-up-to-1-000-entries": "<div class=\"keyword-indexing-1000-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-1-000-entries.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-1-000-entries', this)\">\n                          A computer-generated keyword index lists a page number for a key term each time it occurs in the book. You simply provide Omni with a list of words that you want to appear in the index. Omni will create an index by tagging the selected words during the production process. The resulting alphabetical list of keywords gives the page numbers for each occurrence of the word.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-1-000-entries.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-1-000-entries', this)\">\n                          The success of this type of index depends entirely on the key words you chose. The choice of words needs to be carefully thought through. Do not use simple words or words that repeat constantly throughout the text. For example, if you are writing a cookbook, do not index the word egg. Every time the word \"egg\" is mentioned, the computer will index that page. We presume that egg would show up on many recipe pages. If words are not chosen carefully, the resulting index can be overly long and unusable.\n                        </p>\n\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-1-000-entries.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-1-000-entries', this)\">\n                          Please note: a concordance-type index has no logical organization other than alphabetization, and only exact word matches can be indexed using the approach.\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" style=\"font-size: 0.93rem; line-height: 1.68;\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-1-000-entries.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-1-000-entries', this)\">\n                          *We highly recommend our Professional Index service if you require an industry-standard index. A computer cannot do what a professional, human indexer can—evaluate the significance of each occurrence of a word and whether it's really important to list, develop appropriate cross references and sub-entries, phrase entries in the most useful way, and more. Librarians and reviewers consider a computer-generated word list not simply less useful but a liability to a book.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timing: </span>\n                          <span style=\"color: #57534e;\">Adds two weeks to the design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "computer-generated-keyword-indexing-custom-quote": "<div class=\"keyword-indexing-custom-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.computer-generated-keyword-indexing-custom-quote.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-custom-quote', this)\">\n                          An index of over 1,000 will require a custom quote. Contact your PSA for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-custom-quote.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-custom-quote', this)\">\n                          A computer-generated keyword index lists a page number for a key term each time it occurs in the book. You simply provide Omni with a list of words that you want to appear in the index. Omni will create an index by tagging the selected words during the production process. The resulting alphabetical list of keywords gives the page numbers for each occurrence of the word.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-custom-quote.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-custom-quote', this)\">\n                          The success of this type of index depends entirely on the key words you chose. The choice of words needs to be carefully thought through. Do not use simple words or words that repeat constantly throughout the text. For example, if you are writing a cookbook, do not index the word egg. Every time the word \"egg\" is mentioned, the computer will index that page. We presume that egg would show up on many recipe pages. If words are not chosen carefully, the resulting index can be overly long and unusable.\n                        </p>\n\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.computer-generated-keyword-indexing-custom-quote.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-custom-quote', this)\">\n                          Please note: a concordance-type index has no logical organization other than alphabetization, and only exact word matches can be indexed using the approach.\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" style=\"font-size: 0.93rem; line-height: 1.68;\" data-block-key=\"service.computer-generated-keyword-indexing-custom-quote.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-custom-quote', this)\">\n                          *We highly recommend our Professional Index service if you require an industry-standard index. A computer cannot do what a professional, human indexer can—evaluate the significance of each occurrence of a word and whether it's really important to list, develop appropriate cross references and sub-entries, phrase entries in the most useful way, and more. Librarians and reviewers consider a computer-generated word list not simply less useful but a liability to a book.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timing: </span>\n                          <span style=\"color: #57534e;\">Adds two weeks to the design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "proofreading": "<div class=\"proofreading-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.94rem;\" data-block-key=\"service.proofreading.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('proofreading', this)\">\n                          Prerequisite: An Omni core editorial service, as recommended. Please speak with your editorial consultant for more information.\n                        </p>\n\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.proofreading.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('proofreading', this)\">\n                          As any publishing professional knows, the process of converting a manuscript into a published book is not 100 percent foolproof. Even manuscripts that have undergone a Quality Review can have the occasional remaining error, as even the best copyeditor in the business or the most careful author can inadvertently overlook or create a few mistakes. In fact, for this reason, traditional publishers usually proofread a manuscript twice. This final polish is highly recommended.\n                        </p>\n\n                        <p class=\"fst-italic mb-2 editable-field\" style=\"color: #44403c; font-size: 0.95rem;\" data-block-key=\"service.proofreading.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('proofreading', this)\">\n                          \"I must comment on the meticulous job done by all the editors, including the last. She found things that we all had missed ... It's downright scary that I teach ENGLISH!\"\n                        </p>\n\n                        <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.proofreading.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('proofreading', this)\">\n                          -Robin M. Berard, author of King Tut and the Girl Who Loved Him\n                        </p>\n                      </div>\n                    </div>",
  "do-it-yourself-audiobook": "<div class=\"diy-audiobook-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.do-it-yourself-audiobook.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">\n                          Expand your audience and reach with the power of audiobooks, an increasingly popular and preferred format.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.do-it-yourself-audiobook.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">\n                          Now you can bring your book to life with your own voice.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.do-it-yourself-audiobook.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">\n                          Effortlessly transform your written words into an immersive audiobook using our partner DIY Audiobook platform,{' '}\n                          <a \n                            href=\"https://myaudiobookrecorder.com/\" \n                            target=\"_blank\" \n                            rel=\"noopener noreferrer\" \n                            style=\"color: #ad7d42; font-weight: 600; text-decoration: underline;\"\n                          >\n                            Myaudiobookrecorder.com.\n                          </a>\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.do-it-yourself-audiobook.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">\n                          This service empowers you to record and produce your audiobook, without needing any audio editing experience.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.do-it-yourself-audiobook.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">\n                          Key Features:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.do-it-yourself-audiobook.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">Easy-to-use recording and editing tools</li>\n                          <li class=\"editable-field\" data-block-key=\"service.do-it-yourself-audiobook.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">Six months of access to the virtual recording studio</li>\n                          <li class=\"editable-field\" data-block-key=\"service.do-it-yourself-audiobook.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">Availability of your audiobook through Overdrive, Audible.com, Amazon.com, and iTunes</li>\n                          <li class=\"editable-field\" data-block-key=\"service.do-it-yourself-audiobook.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">ISBN registration</li>\n                        </ul>\n\n                        <p class=\"fst-italic mb-0 editable-field\" style=\"color: #57534e; font-size: 0.91rem;\" data-block-key=\"service.do-it-yourself-audiobook.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">\n                          *Audiobook distribution partners require that the e-book version is in distribution and available for sale.\n                        </p>\n                      </div>\n                    </div>",
  "professional-audiobook-package": "<div class=\"professional-audiobook-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.professional-audiobook-package.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                          Readers have spoken—and we have listened. These days, they prefer books in a format that will easily fit their busy lifestyle. This is why Omni offers you a solution that allows you to tap into your readers’ multitasking ways: audiobooks. Now they can “read” your book while they commute, work out or even as they do their chores.\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.professional-audiobook-package.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                          But exactly how popular are audiobooks among readers? The growing demand is evidently seen the rise of daily downloads of audiobooks year after year. Tap into that market by having your book available in audio format with our help.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.professional-audiobook-package.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                          The Professional Audiobook service includes:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">Audiobook conversion of up to 5,000 words</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">Narration by a professional voice-over actor</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">Your own digital copy of the audiobook</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">Intro, beginning and end background music for your audiobook</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">Availability of your audiobook through Overdrive, Audible.com, Amazon.com and iTunes</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">ISBN Registration</li>\n                        </ul>\n\n                        \n                        <div class=\"audio-samples-card p-4 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <div class=\"mb-4\">\n                            <h5 class=\"fw-bold mb-2 d-flex align-items-center gap-2 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.professional-audiobook-package.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                              <i class=\"bi bi-volume-up-fill\" style=\"color: #ad7d42;\"></i>\n                              Audiobook Sample: Male\n                            </h5>\n                            <audio controls class=\"w-100\" style=\"max-width: 480px; height: 42px;\">\n                              <source src=\"/assets/audio/Jewel in the Wake_Male.mp3\" type=\"audio/mpeg\" />\n                              Your browser does not support the audio element.\n                            </audio>\n                          </div>\n\n                          <div class=\"mb-2\">\n                            <h5 class=\"fw-bold mb-2 d-flex align-items-center gap-2 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.professional-audiobook-package.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                              <i class=\"bi bi-volume-up-fill\" style=\"color: #ad7d42;\"></i>\n                              Audiobook Sample: Female\n                            </h5>\n                            <audio controls class=\"w-100\" style=\"max-width: 480px; height: 42px;\">\n                              <source src=\"/assets/audio/Mask Weavers for Hire_Female.mp3\" type=\"audio/mpeg\" />\n                              Your browser does not support the audio element.\n                            </audio>\n                          </div>\n                        </div>\n\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.professional-audiobook-package.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                          The default retail price set will be $9.99 minimum. Please take note that other distributors and resellers have the sole discretion to set the price of the audiobooks they sell.\n                        </p>\n\n                        <div class=\"p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42; padding: 16px 20px;\">\n                          <p class=\"fw-semibold fst-italic mb-2 editable-field\" style=\"color: #ad7d42; font-size: 0.96rem;\" data-block-key=\"service.professional-audiobook-package.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                            Is your book more than 5,000 words?\n                          </p>\n                          <p class=\"fw-semibold fst-italic mb-2 editable-field\" style=\"color: #ad7d42; font-size: 0.96rem;\" data-block-key=\"service.professional-audiobook-package.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                            Need your audiobook converted right away?\n                          </p>\n                          <p class=\"mb-2 editable-field\" style=\"color: #44403c; font-size: 0.93rem; line-height: 1.65;\" data-block-key=\"service.professional-audiobook-package.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                            We can send you your audiobook in 30 days with our Rapid Release Audiobook service for an additional fee of $500. Please take note of the following conditions:\n                          </p>\n                          <ul class=\"mb-0 ps-3 d-flex flex-column gap-1\" style=\"color: #57534e; font-size: 0.9rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">Your manuscript should only have a maximum of 30,000 words.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li8\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">You need to approve the audiobook sample we will send you before we can get started on your audiobook. Your 30-day countdown will start from the day we receive your demo approval.</li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "softcover-publishing": "<div class=\"softcover-publishing-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.softcover-publishing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                          Softcover Format is already included in select publishing packages and cannot be purchased separately. This page is designed to give you more information about the service and why it’s important for your book.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.softcover-publishing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                          Omni softcover books are formatted as trade paperbacks. Trade paperback is an industry term that describes a book that is of better production quality. These books are produced in a larger size and offered at a higher price than a mass-market paperback format. Mass-market paperbacks are generally cheaply made and printed on newsprint or other low-quality paper, which will discolor and disintegrate over time. Trade paperbacks, on the other hand, meet a higher standard and are printed on high-quality paper.\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.softcover-publishing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                          Omni offers trade paperbacks in the following trim sizes:\n                        </p>\n\n                        <div class=\"row g-4 mb-4\">\n                          <div class=\"col-12 col-md-6\">\n                            <div class=\"p-3.5 rounded-3 h-100\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                              <h5 class=\"fw-bold mb-3 d-flex align-items-center gap-2 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.softcover-publishing.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                                <i class=\"bi bi-book-half\" style=\"color: #ad7d42;\"></i>\n                                Black & White Trim sizes\n                              </h5>\n                              <ul class=\"mb-0 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">5\" x 8\"</li>\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">5.5\" x 8.5\"</li>\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">6\" x 9\"</li>\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">7.5\" x 9.25\"</li>\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">8.25\" x 11\"</li>\n                              </ul>\n                            </div>\n                          </div>\n                          <div class=\"col-12 col-md-6\">\n                            <div class=\"p-3.5 rounded-3 h-100\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                              <h5 class=\"fw-bold mb-3 d-flex align-items-center gap-2 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.softcover-publishing.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                                <i class=\"bi bi-palette-fill\" style=\"color: #ad7d42;\"></i>\n                                Color Trim Sizes\n                              </h5>\n                              <ul class=\"mb-0 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">8.5\" x 8.5\"</li>\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">8.5\" x 11\"</li>\n                              </ul>\n                            </div>\n                          </div>\n                        </div>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.softcover-publishing.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                          Omni softcover books are printed on high-quality, acid-free, book-grade opaque paper stock in black and white or grayscale halftones. Softcovers are printed on a bright white cover stock in full color.\n                        </p>\n\n                        <p class=\"fst-italic mb-0 editable-field\" style=\"color: #57534e; font-size: 0.91rem;\" data-block-key=\"service.softcover-publishing.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                          *Books included in publishing packages will be shipped at standard shipping rates.\n                        </p>\n                      </div>\n                    </div>",
  "hardcover-publishing": "<div class=\"hardcover-publishing-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.hardcover-publishing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">\n                          For durability and class, our black & white hardcover publishing is available in your choice of two formats: glossy casebound or dust jacket. The casebound option features a full-color glossy cover image adhered directly to the cover. The dust jacket option features a blue digital cloth cover with a digitally printed non-metallic gold-colored ink onto the spine and a full-color dust jacket with flaps. The full-color dust jacket allows us to print your author biography and a description of your book on the inside flaps, freeing up the back cover to print reviews and endorsements. Your hardcover edition will also be assigned a unique ISBN. In addition to the paperback copies included in your publishing package, you will receive one free author copy of your hardcover edition.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h5 class=\"fw-bold mb-3 d-flex align-items-center gap-2 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.hardcover-publishing.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">\n                            <i class=\"bi bi-journal-bookmark-fill\" style=\"color: #ad7d42;\"></i>\n                            Black & White Specifications\n                          </h5>\n                          <ul class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">Page count range of 108-800</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">\n                              You can choose between these two trim sizes:\n                              <ul class=\"ps-3 mt-1 d-flex flex-column gap-1\">\n                                <li>5.5” × 8.5”</li>\n                                <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">6” × 9”</li>\n                              </ul>\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold fst-italic mb-2\" style=\"color: #ad7d42; font-size: 0.95rem;\">\n                            Please note:\n                          </h6>\n                          <ul class=\"fst-italic mb-0 ps-3 d-flex flex-column gap-1.5\" style=\"color: #57534e; font-size: 0.91rem; line-height: 1.6;\">\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">When publishing a hardcover book, the softcover trim size must match that of the hardcover.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">You can provide additional text for the interior flaps of the case-laminated cover, such as an excerpt of a book review or endorsement.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">During book production, you will be given the opportunity to proof both the softcover and hardcover editions of your cover and suggest changes as appropriate.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">Due to the higher production costs, the retail price for hardcover books may be more than softcover books.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li8\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">The delivery time for hardcover book orders is about seven days longer than for softcover books.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li9\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">Author pen name must not exceed 38 characters.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li10\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">Prices are subject to change without prior notice. Some restrictions may apply.</li>\n                          </ul>\n                        </div>\n\n                        <p class=\"mb-0 fw-medium editable-field\" style=\"color: #2b2219;\" data-block-key=\"service.hardcover-publishing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">\n                          Your book will be a keepsake for generations to come when you choose to preserve your book in long-lasting hardcover format.\n                        </p>\n                      </div>\n                    </div>",
  "book-binding-sizes-and-types": "<div class=\"book-binding-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.book-binding-sizes-and-types.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('book-binding-sizes-and-types', this)\">\n                          Please note: These binding and paper options cannot be purchased separately. This page is designed to give you more information about the service and why it’s important for your book.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.book-binding-sizes-and-types.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('book-binding-sizes-and-types', this)\">\n                          Omni publishes softcover books in perfect-bound format, a type of book binding that uses glue to hold the pages and cover together (typical of most professional books found in stores). We also publish hardcover books in two trim sizes: 5.5\" x 8.5\" or 6\" x 9\". We do not publish wire-o, plasticomb, three-ring, nor spiral-bound books.\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.book-binding-sizes-and-types.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('book-binding-sizes-and-types', this)\">\n                          The chart below lists the binding and paper options available to you at Omni:\n                        </p>\n\n                        <div class=\"mb-4\">\n                          <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.book-binding-sizes-and-types.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('book-binding-sizes-and-types', this)\">\n                            Softcover Sizes and Options\n                          </h5>\n                          <div class=\"table-responsive rounded-3 border\" style=\"border-color: #ebd9c4;\">\n                            <table class=\"table table-hover mb-0\" style=\"font-size: 0.92rem;\">\n                              <thead style=\"background: #f8f4ee; color: #2b2219;\">\n                                <tr>\n                                  <th class=\"py-2.5 px-3\">Trim Size</th>\n                                  <th class=\"py-2.5 px-3\">Paper Specifications</th>\n                                  <th class=\"py-2.5 px-3\">Paper Color</th>\n                                </tr>\n                              </thead>\n                              <tbody>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">5\" × 8\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">White or Crème</td></tr>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">5.5\" × 8.5\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">White or Crème</td></tr>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">6\" × 9\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">White or Crème</td></tr>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">7.5\" × 9.25\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">White</td></tr>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">8.25\" × 11\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">White</td></tr>\n                              </tbody>\n                            </table>\n                          </div>\n                        </div>\n\n                        <div class=\"mb-4\">\n                          <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.book-binding-sizes-and-types.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('book-binding-sizes-and-types', this)\">\n                            Color Softcover Sizes and Options\n                          </h5>\n                          <div class=\"table-responsive rounded-3 border\" style=\"border-color: #ebd9c4;\">\n                            <table class=\"table table-hover mb-0\" style=\"font-size: 0.92rem;\">\n                              <thead style=\"background: #f8f4ee; color: #2b2219;\">\n                                <tr>\n                                  <th class=\"py-2.5 px-3\">Trim Size</th>\n                                  <th class=\"py-2.5 px-3\">Paper Specifications</th>\n                                  <th class=\"py-2.5 px-3\">Paper Color</th>\n                                </tr>\n                              </thead>\n                              <tbody>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">8.5\" × 8.5\"</td><td class=\"py-2.5 px-3\">70 lb, acid-free</td><td class=\"py-2.5 px-3\">White</td></tr>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">8.5\" × 11\"</td><td class=\"py-2.5 px-3\">70 lb, acid-free</td><td class=\"py-2.5 px-3\">White</td></tr>\n                              </tbody>\n                            </table>\n                          </div>\n                        </div>\n\n                        <div class=\"mb-3\">\n                          <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.book-binding-sizes-and-types.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('book-binding-sizes-and-types', this)\">\n                            Hardcover Sizes and Options\n                          </h5>\n                          <div class=\"table-responsive rounded-3 border\" style=\"border-color: #ebd9c4;\">\n                            <table class=\"table table-hover mb-0\" style=\"font-size: 0.92rem;\">\n                              <thead style=\"background: #f8f4ee; color: #2b2219;\">\n                                <tr>\n                                  <th class=\"py-2.5 px-3\">Trim Size</th>\n                                  <th class=\"py-2.5 px-3\">Paper Specifications</th>\n                                  <th class=\"py-2.5 px-3\">Paper Color</th>\n                                </tr>\n                              </thead>\n                              <tbody>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">5.5\" × 8.5\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">Crème</td></tr>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">6\" × 9\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">Crème</td></tr>\n                              </tbody>\n                            </table>\n                          </div>\n                        </div>\n                      </div>\n                    </div>",
  "black-and-white-illustrations-fine-detail": "<div class=\"illustration-fine-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">\n                          Introduce a new level of artistry to your book by including beautiful black-and-white imagery that will enhance your readers’ experience of your book. With Omni's Fine Detail line of custom black-and-white illustrations, basic highlights and shadows will be added to illustrated objects and sceneries to add a greater level of depth and dimension. Our talented team of in-house studio artists will use your ideas and creative direction to produce images that can help strengthen both your book’s message and marketability.\n                        </p>\n                        \n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.black-and-white-illustrations-fine-detail.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">\n                          Your black-and-white illustrations can be produced in the following styles:\n                        </h5>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">Juvenile/Whimsical (a sweet, cute style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">Cartoon/Humor (a humorous, funny style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">Fantasy (a comic-book or mythical style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">Science Fiction (a futuristic or technological style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">Naturalistic (a true-to-life style)</li>\n                        </ul>\n\n                        <div class=\"text-center my-4\">\n                          <img src=\"/assets/img/illustration.jpg\" alt=\"Fine Detail Illustration Sample\" class=\"img-fluid rounded-3 shadow-sm\" style=\"max-height: 380px;\" />\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timeline: </span>\n                          <span style=\"color: #57534e;\">Six to 12 weeks depending on work queue and project complexity</span>\n                        </div>\n                      </div>\n                    </div>",
  "black-and-white-illustrations-personalized": "<div class=\"illustration-personalized-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.black-and-white-illustrations-personalized.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">\n                          You already did the impressive work of writing a book. Now let Omni help you enhance it with custom black-and-white illustrations. Our talented artists will use your ideas and creative direction to create unique illustrations that will fit perfectly with your book. The clean lines and uniform shading used in creating Personalized illustrations are perfect for a simple, classic look. These black-and-white illustrations can be created in a wide variety of styles and subject matter, from people and landscapes to technical drawings and maps.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.black-and-white-illustrations-personalized.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">\n                          Your black-and-white illustrations can be produced in the following styles:\n                        </h5>\n                        <ul class=\"mb-3 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-personalized.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">Juvenile/Whimsical (a sweet, cute style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-personalized.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">Cartoon/Humor (a humorous, funny style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-personalized.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">Fantasy (a comic-book or mythical style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-personalized.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">Science Fiction (a futuristic or technological style)</li>\n                        </ul>\n\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.black-and-white-illustrations-personalized.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">\n                          Our artists can also create illustrations in a realistic style; however, you'll need to select our Fine Detail illustration service.\n                        </p>\n\n                        <div class=\"text-center my-4\">\n                          <img src=\"/assets/img/illustration.jpg\" alt=\"Personalized Illustration Sample\" class=\"img-fluid rounded-3 shadow-sm\" style=\"max-height: 380px;\" />\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timeline: </span>\n                          <span style=\"color: #57534e;\">Six to 12 weeks depending on work queue and project complexity</span>\n                        </div>\n                      </div>\n                    </div>",
  "color-illustrations-intricate-design": "<div class=\"color-illustrations-intricate-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-intricate-design.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">\n                          Intricate Design color illustrations are created by hand and still consist of defining outlines but with varying degrees of line details. By giving greater levels of shading and highlights within the line art, the artist creates more three-dimensional illustrations. This is the only level where the art can be colored digitally or by hand.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-intricate-design.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">\n                          By adding details and textures and varying color values, your illustrator will add a high level of 3-dimensionality to your color illustrations. Omni's in-house studio artists will use your ideas and description of your characters and storyline to create unique artwork that is appropriate your book and its target audience.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.color-illustrations-intricate-design.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">\n                          Your full-color illustrations can be produced in the following styles:\n                        </h5>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-intricate-design.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">Juvenile/Whimsical (a sweet, cute style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-intricate-design.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">Cartoon/Humor (a humorous, funny style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-intricate-design.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">Fantasy (a comic-book or mythical style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-intricate-design.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">Science Fiction (a futuristic or technological style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-intricate-design.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">Naturalistic (a true-to-life style)</li>\n                        </ul>\n\n                        <div class=\"text-center my-4\">\n                          <img src=\"/assets/img/colored.jpg\" alt=\"Intricate Color Illustration Sample\" class=\"img-fluid rounded-3 shadow-sm\" style=\"max-height: 380px;\" />\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timeline: </span>\n                          <span style=\"color: #57534e;\">Six to 12 weeks depending on work queue and project complexity</span>\n                        </div>\n                      </div>\n                    </div>",
  "color-illustrations-fine-detail": "<div class=\"color-illustrations-fine-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-fine-detail.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">\n                          Enhance your readers' experience with detailed and vibrant illustrations. The Fine Detail illustrations created for your book will be drawn by hand and colored digitally. At this level of artistry, your Omni illustrator will add basic shadows and highlights to objects and scenery, giving your book’s artwork a greater level of depth and dimension.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.color-illustrations-fine-detail.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">\n                          Your full-color illustrations can be produced in the following styles:\n                        </h5>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-fine-detail.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">Juvenile/Whimsical (a sweet, cute style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-fine-detail.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">Cartoon/Humor (a humorous, funny style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-fine-detail.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">Fantasy (a comic-book or mythical style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-fine-detail.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">Science Fiction (a futuristic or technological style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-fine-detail.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">Naturalistic (a true-to-life style)</li>\n                        </ul>\n\n                        <div class=\"text-center my-4\">\n                          <img src=\"/assets/img/colored.jpg\" alt=\"Fine Detail Color Illustration Sample\" class=\"img-fluid rounded-3 shadow-sm\" style=\"max-height: 380px;\" />\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timeline: </span>\n                          <span style=\"color: #57534e;\">Six to 12 weeks depending on work queue and project complexity</span>\n                        </div>\n                      </div>\n                    </div>",
  "color-illustrations-personalized": "<div class=\"color-illustrations-personalized-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-personalized.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">\n                          Elevate your book to the next creative level with artwork produced by our talented illustration team. Omni's in-house studio artists will follow your ideas and direction to produce striking artwork that accentuates your carefully crafted book.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-personalized.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">\n                          With Personalized illustrations, art is drawn by hand and colored digitally. The clean lines and uniform colors create a simple style that will add a classic look to your book. These full-color illustrations can be created in a wide variety of styles and subject matter, from people and landscapes to technical drawings and maps.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.color-illustrations-personalized.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">\n                          Your full-color illustrations can be produced in the following styles:\n                        </h5>\n                        <ul class=\"mb-3 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-personalized.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">Juvenile/Whimsical (a sweet, cute style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-personalized.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">Cartoon/Humor (a humorous, funny style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-personalized.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">Fantasy (a comic-book or mythical style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-personalized.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">Science Fiction (a futuristic or technological style)</li>\n                        </ul>\n\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.color-illustrations-personalized.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">\n                          Our artists can also create illustrations in a more realistic style; however, you'll need to select our Fine Detail or Intricate Design illustrations.\n                        </p>\n\n                        <div class=\"text-center my-4\">\n                          <img src=\"/assets/img/colored.jpg\" alt=\"Personalized Color Illustration Sample\" class=\"img-fluid rounded-3 shadow-sm\" style=\"max-height: 380px;\" />\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timeline: </span>\n                          <span style=\"color: #57534e;\">Six to 12 weeks depending on work queue and project complexity</span>\n                        </div>\n                      </div>\n                    </div>",
  "elite-cover-design": "<div class=\"elite-cover-design-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.elite-cover-design.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">\n                          Please Note: Elite Cover Design is included in select publishing packages and cannot be purchased separately. This page is designed to give you more information about the service and why it is important for your book.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.elite-cover-design.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">\n                          A potential reader’s decision to learn more about your book is often determined by the appeal of your book’s cover. Although we’ve all been told to “never judge a book by its cover,” it’s hard not to let a book’s visual appearance sway our judgment when there are so many books to choose from. One of the primary ways to entice readers to discover and purchase your book over thousands of other books is by capturing their interest with a compelling cover design.\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.elite-cover-design.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">\n                          With Omni’s Elite Cover Design, you will work one-on-one with a professional cover designer who will be committed to creating a cover that compliments your written work and gives your book its best shot at success in today’s competitive market.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.elite-cover-design.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">\n                          The Elite Difference:\n                        </h5>\n                        <ul class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.elite-cover-design.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">Your Omni cover designer will conduct creative research on genre-specific cover trends to determine which design will maximize your book's impact in the marketplace.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.elite-cover-design.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">Your designer will propose three front cover concepts that reflect the feel of your book.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.elite-cover-design.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">Once you choose your favorite concept, you and your designer will confirm the details about the design elements.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.elite-cover-design.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">You will receive the first draft of the cover and have one free round of corrections.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.elite-cover-design.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">After your designer incorporates any changes per your request to your design, you’ll receive your final cover as a PDF (Please note: any changes requested after the initial round of free corrections will incur a fee).</li>\n                        </ul>\n                      </div>\n                    </div>",
  "custom-cover-illustration": "<div class=\"custom-cover-illustration-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.custom-cover-illustration.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">\n                          If you want your idea translated into an original piece of art, you've come to the right place. Our team of experienced in-house artists will work with you to produce a striking custom cover illustration that will help your book stand out.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.custom-cover-illustration.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">\n                            How Does a Custom Cover Illustration Benefit You and Your Book?\n                          </h5>\n                          <ul class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.custom-cover-illustration.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">People really do judge a book by its cover—first and foremost, the purpose of your book cover is to make people pick up your book, or click on the virtual version.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.custom-cover-illustration.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">The artwork created is unique to your book, which both readers and booksellers will notice.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.custom-cover-illustration.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">Artwork can be created in a variety of mediums depending on what you think will enhance your book.</li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.custom-cover-illustration.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">\n                            How Does the Process Work?\n                          </h5>\n                          <ol class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.custom-cover-illustration.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">You’ll connect with our art team to discuss the initial book cover concept and timelines.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.custom-cover-illustration.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">They’ll create a sketch from your instructions and work with you through two free rounds of revisions if necessary to create a final illustration to your specifications.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.custom-cover-illustration.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">You’ll work with our design team to create a finished book cover using the final artwork.</li>\n                          </ol>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h5 class=\"fw-bold mb-2 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.custom-cover-illustration.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">\n                            More About | Custom Cover Illustration\n                          </h5>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.95rem; line-height: 1.65;\" data-block-key=\"service.custom-cover-illustration.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">\n                            Illustrations usually take <strong>6 to 12 weeks</strong> to complete depending on our work queue and the complexity of your project.\n                          </p>\n                        </div>\n\n                        <div class=\"text-center my-4\">\n                          <img src=\"/assets/img/colored.jpg\" alt=\"Cover Illustration Sample\" class=\"img-fluid rounded-3 shadow-sm\" style=\"max-height: 380px;\" />\n                        </div>\n                      </div>\n                    </div>",
  "cover-revisions-text": "<div class=\"cover-revisions-text-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.cover-revisions-text.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">\n                          Cover Revisions (Text) are corrections that are made to the text on the cover layout. During your publication process, you are given one round of revisions to the cover at no charge. If after this initial round of edits you would like some additional modifications, this design service enables you to make text changes to your cover for a fee.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.cover-revisions-text.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">\n                          Text adjustments range from:\n                        </h5>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-text.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">replacing a few words</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-text.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">correcting punctuation</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-text.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">adding additional quotes and other information</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-text.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">completely replacing sections of cover text</li>\n                        </ul>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.65;\" data-block-key=\"service.cover-revisions-text.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">\n                            It is the author's responsibility to supply Omni with the exact changes, location, and phrases that they would like to change or replace. It is also the responsibility of the author to proofread or edit these changes.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "cover-revisions-images-design": "<div class=\"cover-revisions-images-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.cover-revisions-images-design.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">\n                          Cover Revisions (Images/Design) are changes to imagery and design elements on the cover layout that are NOT text changes. The following services are just a few of many that Omni can complete for an author:\n                        </p>\n\n                        <ul class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-images-design.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">Touch-up photographs</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-images-design.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">Blend several images together</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-images-design.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">Remove components of an image</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-images-design.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">Combine elements from several different images into one scene</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-images-design.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">Changing/manipulating skin color, eye color, scene color</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-images-design.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">Red-eye reduction</li>\n                        </ul>\n                      </div>\n                    </div>",
  "elite-interior-design": "<div class=\"elite-interior-design-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.elite-interior-design.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                          Please Note: Elite Interior Design is included in select publishing packages and cannot be purchased separately. This page is designed to give you more information about the service and why it’s important for your book.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.elite-interior-design.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                          With Elite Interior Design, you will hold a one-on-one consultation with an Omni book layout specialist who has special training in designing for your book’s genre. Using your ideas and input, your designer will create the interior page layout your book needs.\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.elite-interior-design.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                          This interior will include chapter titles, headings, page numbers and other layout details that will allow for easy reading and ensure your book meets industry standards. The layout designer will also insert photos or graphics and conduct minimal manuscript cleanup.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.elite-interior-design.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                          Here’s how it works:\n                        </h5>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">Your Omni designer will conduct creative research on genre-specific book layout trends to determine which design will maximize your book's impact in the marketplace.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">Your designer will discuss concepts that reflect the feel of your book (such as fonts, chapter starts, title page design, etc.).</li>\n                          <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">Your designer will then create three mock-ups of the front matter, including the first few pages of the first chapter.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">Once you choose your favorite concept, we will confirm the details about the design elements.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">You will receive the first draft of the completed layout as a PDF and have one round of 50 free corrections.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">After your designer incorporates any changes, you’ll receive your final galley as a PDF (Please Note: Any changes requested after the initial round of free corrections will incur a fee).</li>\n                        </ul>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219;\">\n                            Margin Guidance:\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.elite-interior-design.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                            During this process, the designer will change your manuscript’s margins to fit your chosen book size. We strongly recommend changing the margins yourself so you can see how the text will look in your book’s final dimensions. This will help you catch any formatting errors caused by text shifts or line breaks that might otherwise result in a delay in your book’s production.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219;\">\n                            Image and Non-Text Submission Requirements:\n                          </h6>\n                          <ul class=\"mb-2 ps-3 d-flex flex-column gap-1.5\" style=\"color: #57534e; font-size: 0.92rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">Submitted separately from your manuscript as a TIFF (.tif) file format</li>\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li8\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">CMYK colorspace</li>\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li9\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">300-dpi resolution</li>\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li10\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">Written copyright permission from the creator (artist, photographer, etc.) to use the work in your book</li>\n                          </ul>\n                          <p class=\"fst-italic mb-0 editable-field\" style=\"color: #78716c; font-size: 0.86rem;\" data-block-key=\"service.elite-interior-design.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                            Exception: Sample graphics and other illustrations used only as ideas or guidelines for the design team can be submitted in any format.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "color-image-insertion": "<div class=\"color-image-insertion-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-image-insertion.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">\n                          If you want to insert additional graphics beyond the allotted number of image insertions of your chosen package, follow the guidelines below. Note that images refer to color photos, tables, charts, diagrams, etc.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.color-image-insertion.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">\n                          Submission Guidelines for Inserting Color Graphics into the Interior of Your Book:\n                        </h5>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.color-image-insertion.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">All interior color graphics (including photos, tables, charts, diagrams, drawings, foreign fonts, and anything else that is not text or would be considered a graphic) should be submitted as individual TIFF (.tif) files.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-image-insertion.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">The manuscript should identify placeholders for each of the interior graphics.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-image-insertion.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">There is a fee for each additional image inserted into the manuscript.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-image-insertion.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">The book cover does not \"count\" as a graphic. It is in full color for no additional charge.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-image-insertion.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">Printer slang for \"full color\" is \"four color\"; this means the full range of colors, not literally just four colors.</li>\n                        </ul>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n                          <span style=\"color: #57534e;\">During design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "custom-layout-tech": "<div class=\"custom-layout-tech-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.custom-layout-tech.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-layout-tech', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.custom-layout-tech.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-layout-tech', this)\">\n                          Certain books may require a specialized layout technician to work with you on your specific custom layout requirements.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration & Cost: </span>\n                          <span style=\"color: #57534e;\">Dependent on complexity</span>\n                        </div>\n                      </div>\n                    </div>",
  "table-of-contents-two-or-more": "<div class=\"toc-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.table-of-contents-two-or-more.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('table-of-contents-two-or-more', this)\">\n                          Please speak to your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.table-of-contents-two-or-more.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('table-of-contents-two-or-more', this)\">\n                          Creating a table of contents for your work will demonstrate to your reader how the information has been organized. In order to better organize your work, multiple tables of contents might be necessary. After the first free table of contents, Omni can create your additional tables of contents with this service.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n                          <span style=\"color: #57534e;\">Dependent on quantity and complexity</span>\n                        </div>\n                      </div>\n                    </div>",
  "table-creation": "<div class=\"table-creation-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.table-creation.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('table-creation', this)\">\n                          Please do not order without first speaking with your publishing services associate.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.table-creation.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('table-creation', this)\">\n                          Our designers can create and format professional tables to be inserted into your manuscript as needed.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration & Cost: </span>\n                          <span style=\"color: #57534e;\">Dependent on quantity and complexity</span>\n                        </div>\n                      </div>\n                    </div>",
  "footnote-formatting": "<div class=\"footnote-formatting-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.footnote-formatting.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('footnote-formatting', this)\">\n                          Adding footnotes to your manuscript can be very useful. Omni follows the Chicago Manual of Style citation guidelines when inserting footnotes for you. Most often, footnotes are used as a replacement for long, explanatory notes. They can also be used for other various reasons:\n                        </p>\n\n                        <ul class=\"mb-3 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.footnote-formatting.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('footnote-formatting', this)\">To direct the reader to more information pertaining to the subject in the main text;</li>\n                          <li class=\"editable-field\" data-block-key=\"service.footnote-formatting.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('footnote-formatting', this)\">To reference a quote or viewpoint; or</li>\n                          <li class=\"editable-field\" data-block-key=\"service.footnote-formatting.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('footnote-formatting', this)\">To use as an alternative to parenthetical references.</li>\n                        </ul>\n\n                        <p class=\"mb-3 editable-field\" style=\"font-size: 0.93rem; line-height: 1.68;\" data-block-key=\"service.footnote-formatting.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('footnote-formatting', this)\">\n                          Footnotes are indicated by a superscript number that corresponds to a note at the bottom of the page that is written in a smaller font and labeled with the same number. It also includes the citation number in superscript and contains the full citation the first time the source is cited. Every subsequent citation of the source only requires an abbreviated citation. The first line of all footnotes is indented, single spaced, and without extra space between references.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n                          <span style=\"color: #57534e;\">During design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "custom-headers": "<div class=\"custom-headers-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.custom-headers.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-headers', this)\">\n                          You may find it important to create custom headers within your book. If at any time during the submission process you would like to change a header within your work, you simply need to purchase our Custom Header service.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n                          <span style=\"color: #57534e;\">During design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "b-w-image-insertion": "<div class=\"bw-image-insertion-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.b-w-image-insertion.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">\n                          If you want to insert additional graphics beyond the allotted number of image insertions of your chosen package, follow the guidelines below. Note that images refer to photos, tables, charts, diagrams, etc.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.b-w-image-insertion.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">\n                          Submission Guidelines for Inserting Graphics into the Interior of Your Book:\n                        </h5>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.b-w-image-insertion.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">All interior graphics (including photos, tables, charts, diagrams, drawings, foreign fonts, and anything else that is not text or would be considered a graphic) should be submitted as individual TIFF (.tif) files.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.b-w-image-insertion.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">The manuscript should identify placeholders for each of the interior graphics.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.b-w-image-insertion.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">There is a fee per additional image inserted into the manuscript.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.b-w-image-insertion.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">All illustrations are produced in black and white or grayscale; we cannot process color inside the manuscript.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.b-w-image-insertion.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">The book cover does not \"count\" as a graphic. It is in full color for no additional charge.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.b-w-image-insertion.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">Printer slang for \"full color\" is \"four color\"; this means the full range of colors, not literally just four colors.</li>\n                        </ul>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <div class=\"mb-2\">\n                            <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n                            <span style=\"color: #57534e;\">During design process</span>\n                          </div>\n                          <p class=\"fst-italic mb-0 editable-field\" style=\"color: #78716c; font-size: 0.86rem; line-height: 1.6;\" data-block-key=\"service.b-w-image-insertion.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">\n                            Disclaimer: Prices listed do not include applicable taxes, which will be added at the time of purchase. Shipping and handling will be calculated and charged after your book is made available for sale.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "interior-revisions-block-of-25": "<div class=\"interior-revisions-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.interior-revisions-block-of-25.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('interior-revisions-block-of-25', this)\">\n                          Omni gives you one opportunity to examine your book proofs and make up to 50 corrections for free. It is imperative that you list these corrections on the proof form provided in order for the changes to be made. Publisher errors such as hyphenation errors, formatting issues or misplaced graphics which occurred during production must also be noted on the proof from, but will not count against the first free 50 corrections.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.interior-revisions-block-of-25.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('interior-revisions-block-of-25', this)\">\n                          Remember to carefully review each page of your proofs for any formatting or typographical errors that were created by either you or Omni. Our proofing process is designed to give you the final say about your book’s appearance by allowing you to rectify any remaining problems or errors.\n                        </p>\n                        <p class=\"mb-3 editable-field\" style=\"color: #57534e; font-size: 0.94rem;\" data-block-key=\"service.interior-revisions-block-of-25.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('interior-revisions-block-of-25', this)\">\n                          If you wish to make further proofreading corrections after the initial free 50, there is a charge for every group of 25 changes.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n                          <span style=\"color: #57534e;\">7-10 Business days</span>\n                        </div>\n                      </div>\n                    </div>",
  "stock-image-processing": "<div class=\"stock-image-processing-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.stock-image-processing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('stock-image-processing', this)\">\n                          All books published via the Omni standard publishing packages receive custom-designed covers, produced in full color. Within the realm of this custom-designed cover, you have the option to choose two images, free of charge, from the millions found through Getty Images. If you wish to include more than two images on your cover, a Stock Image Processing fee will be assessed.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.stock-image-processing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('stock-image-processing', this)\">\n                          This fee will also be placed on any images found through Getty Images you wish to use in the interior of your book.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-2 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.65;\" data-block-key=\"service.stock-image-processing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('stock-image-processing', this)\">\n                            To avoid these fees please adhere to the manuscript submission guidelines. Speak to an Omni team member for more information about this service.\n                          </p>\n                          <p class=\"fst-italic mb-0 editable-field\" style=\"color: #78716c; font-size: 0.86rem; line-height: 1.6;\" data-block-key=\"service.stock-image-processing.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('stock-image-processing', this)\">\n                            Disclaimer: Prices listed do not include applicable taxes, which will be added at the time of purchase. Shipping and handling will be calculated and charged after your book is made available for sale.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "retech": "<div class=\"retech-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.retech.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retech', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.retech.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retech', this)\">\n                          Once you have received your first interior proof from your design team, it is possible that the number of errors (usually more than 100 corrections) is such that it's in your best interest to supply us with a revised manuscript to reformat into a new interior proof for you to review. If the retech service is done at your request, there is an initial charge for the retech service and any applicable special formatting fees will need to be paid again (indexing, tables, etc.). Please contact your Publishing Services Associate for a complete quote.\n                        </p>\n\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.retech.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retech', this)\">\n                          In addition to providing a new manuscript, you will also have another opportunity to re-select your book’s trim size and provide revised formatting suggestions to your Publishing Services Associate. This includes changes of typeface, type size, image treatments, and the overall style in which your book was formatted. It is important that you express these types of formatting requests to your Publishing Services Associate, or supply an interior proof form, along with your newly revised manuscript. If we do not receive revised formatting requests, then the design team will utilize the same styling as the first proof you received from us.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219;\">\n                            Resubmission Discount:\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.retech.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retech', this)\">\n                            Please Note: If you are resubmitting to do a retech then the price of the retech is reduced when purchased with the resubmission.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3.5 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219;\">\n                            More About | Retech\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.retech.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retech', this)\">\n                            If additional revisions are needed, this is the perfect opportunity to make your book shine.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "title-change-after-setup": "<div class=\"title-change-after-setup-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.title-change-after-setup.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('title-change-after-setup', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.title-change-after-setup.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('title-change-after-setup', this)\">\n                          If an author wants to make changes to the title it impacts many elements within the book and through the registration and marketing of the book.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.title-change-after-setup.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('title-change-after-setup', this)\">\n                            Changing the title of your book impacts the cover design, interior layout, ISBN assignment, copyright records, and metadata across worldwide retail channels. Contact your Publishing Services Associate to coordinate a seamless title update.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "color-image-scanning": "<div class=\"color-image-scanning-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.color-image-scanning.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-scanning', this)\">\n                          Authors who send in hard copies of original color images can have them scanned and placed into the correct place in your work.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-image-scanning.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-scanning', this)\">\n                          Omni allows usage of original color art to be placed within a manuscript. Authors who send in hard copies may purchase the Color Image Scanning service. Omni will take the original image and scan it into the correct place in your work.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.color-image-scanning.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-scanning', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 1-2 Weeks dependent on quantity\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "basic-manuscript-formatting-corrections": "<div class=\"basic-manuscript-formatting-corrections-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.basic-manuscript-formatting-corrections.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.basic-manuscript-formatting-corrections.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">\n                          We often receive manuscripts that require formatting corrections before we can start the editorial and layout processes. These include:\n                        </p>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #57534e; font-size: 0.94rem; line-height: 1.8;\">\n                          <li class=\"editable-field\" data-block-key=\"service.basic-manuscript-formatting-corrections.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">Removing headers, footers, page numbering, etc.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.basic-manuscript-formatting-corrections.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">Inserting page breaks appropriately</li>\n                          <li class=\"editable-field\" data-block-key=\"service.basic-manuscript-formatting-corrections.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">Correcting soft and hard returns</li>\n                          <li class=\"editable-field\" data-block-key=\"service.basic-manuscript-formatting-corrections.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">Correcting line and paragraph formatting</li>\n                        </ul>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.basic-manuscript-formatting-corrections.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">\n                            <strong style=\"color: #2b2219;\">Submission Tip:</strong> To avoid these fees please adhere to the manuscript submission guidelines.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "extensive-customized-formatting": "<div class=\"extensive-customized-formatting-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.extensive-customized-formatting.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.extensive-customized-formatting.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">\n                          Occasionally we receive manuscripts that require an extensive amount of formatting before we can start the editorial and layout process.\n                        </p>\n\n                        <p class=\"fw-semibold mb-2 editable-field\" style=\"color: #2b2219; font-size: 0.95rem;\" data-block-key=\"service.extensive-customized-formatting.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">\n                          This includes:\n                        </p>\n                        <ul class=\"mb-4 ps-3\" style=\"color: #57534e; font-size: 0.94rem; line-height: 1.8;\">\n                          <li class=\"editable-field\" data-block-key=\"service.extensive-customized-formatting.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">Removing text boxes</li>\n                          <li class=\"editable-field\" data-block-key=\"service.extensive-customized-formatting.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">Removing embedded graphics</li>\n                          <li class=\"editable-field\" data-block-key=\"service.extensive-customized-formatting.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">Removing wrapped text, etc.</li>\n                        </ul>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.extensive-customized-formatting.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">\n                            <strong style=\"color: #2b2219;\">Submission Tip:</strong> To avoid these fees please adhere to the manuscript submission guidelines.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.extensive-customized-formatting.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">\n                            <strong style=\"color: #2b2219;\">Duration & Scope:</strong> Duration and cost are dependent on quantity and complexity.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "data-entry-standard": "<div class=\"data-entry-standard-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.data-entry-standard.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-standard', this)\">\n                          With Standard Data Entry, you can send us your printed manuscript and we will convert it into a working digital file. This excludes any handwritten documents or newspaper-type articles.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.data-entry-standard.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-standard', this)\">\n                          In order for our professional staff to efficiently work on your manuscript, Omni must have a digital file to manipulate. Leave it to the Omni team of professionals to convert your printed document.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.data-entry-standard.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-standard', this)\">\n                            <strong style=\"color: #2b2219;\">Notice:</strong> This excludes any handwritten documents or newspaper-type articles. For handwritten works, please select our Data Entry - Handwritten service.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.data-entry-standard.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-standard', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 30-45 business days dependent on page count\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "data-entry-spanish": "<div class=\"data-entry-spanish-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.data-entry-spanish.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-spanish', this)\">\n                          Spanish-language materials you provide are converted into an electronic format for publication with our Spanish Data Entry service.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.data-entry-spanish.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-spanish', this)\">\n                          In order for our professional staff to efficiently work on your manuscript, Omni must have a digital file to manipulate. The Data Entry - Spanish service will convert typed Spanish-language material that you have provided into an electronic format for publication.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.data-entry-spanish.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-spanish', this)\">\n                            <strong style=\"color: #2b2219;\">Notice:</strong> This excludes any handwritten documents or newspaper-type articles.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.data-entry-spanish.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-spanish', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 60-75 days\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "data-entry-handwritten": "<div class=\"data-entry-handwritten-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.data-entry-handwritten.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-handwritten', this)\">\n                          Relieve yourself from the tedious task of encoding multiple pages and let us do all the manual encoding for you. This service is only applicable to handwritten documents.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.data-entry-handwritten.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-handwritten', this)\">\n                          Is your manuscript handwritten? Now you have the option to have your book converted into a digital file. In order for our professional staff to efficiently work on your manuscript, Omni must have a digital file to manipulate. Leave it to the Omni team of professionals to manually type and convert your document.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.data-entry-handwritten.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-handwritten', this)\">\n                            <strong style=\"color: #2b2219;\">Service Note:</strong> This service will only be applied to handwritten documents.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "large-image-scanning": "<div class=\"large-image-scanning-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.large-image-scanning.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('large-image-scanning', this)\">\n                          Please contact your publishing services consultant for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.large-image-scanning.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('large-image-scanning', this)\">\n                          The Large Image Scanning services include images that are larger than 11\" x 17\". Omni will professionally scan your oversized artwork and visuals to ensure crystal clarity when printed in your book.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.large-image-scanning.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('large-image-scanning', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 2-3 weeks\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "b-w-image-scanning": "<div class=\"b-w-image-scanning-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.b-w-image-scanning.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-scanning', this)\">\n                          Authors who send in hard copies of original black and white images can have them scanned and placed into the correct place in your work.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.b-w-image-scanning.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-scanning', this)\">\n                          Omni allows usage of original black and white art to be placed within a manuscript. Authors who send in hard copies may purchase the Black and White Image Scanning service. Omni will take the original image and scan it into the correct place in your work.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.b-w-image-scanning.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-scanning', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 1-2 Weeks dependent on quantity\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "manuscript-file-conversion": "<div class=\"manuscript-file-conversion-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.manuscript-file-conversion.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('manuscript-file-conversion', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.manuscript-file-conversion.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('manuscript-file-conversion', this)\">\n                          Omni will make every effort to work with manuscripts created using a wide variety of software packages. We will charge a small conversion fee for documents created under such formats as WordPerfect, WordPad, and Microsoft Works.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.manuscript-file-conversion.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('manuscript-file-conversion', this)\">\n                            <strong style=\"color: #2b2219;\">Submission Tip:</strong> To avoid these fees please adhere to the manuscript submission guidelines.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.manuscript-file-conversion.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('manuscript-file-conversion', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 1 week\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "graphic-file-conversions-quantity-25": "<div class=\"graphic-file-conversions-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.graphic-file-conversions-quantity-25.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.graphic-file-conversions-quantity-25.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">\n                          Authors often send in graphic files (these include graphics, tables, text boxes) that require an extensive amount of work. These include:\n                        </p>\n\n                        <ul class=\"mb-3 ps-3\" style=\"color: #57534e; font-size: 0.94rem; line-height: 1.8;\">\n                          <li class=\"editable-field\" data-block-key=\"service.graphic-file-conversions-quantity-25.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">Cropping graphics as requested by the author</li>\n                          <li class=\"editable-field\" data-block-key=\"service.graphic-file-conversions-quantity-25.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">Extracting graphics from the manuscript</li>\n                          <li class=\"editable-field\" data-block-key=\"service.graphic-file-conversions-quantity-25.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">Converting line art to TIFF (.tif) files</li>\n                        </ul>\n\n                        <p class=\"mb-3 editable-field\" style=\"color: #44403c; font-size: 0.95rem;\" data-block-key=\"service.graphic-file-conversions-quantity-25.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">\n                          Your graphic files will be reviewed and a price quoted based on a price per block of 25 graphic files. The author will have the option of making the changes themselves or paying for Omni staff to make the changes.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.graphic-file-conversions-quantity-25.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">\n                            <strong style=\"color: #2b2219;\">Submission Tip:</strong> To avoid these fees please adhere to the image submission guidelines.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.graphic-file-conversions-quantity-25.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 1-2 weeks\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "file-merging": "<div class=\"file-merging-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.file-merging.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('file-merging', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.file-merging.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('file-merging', this)\">\n                          The standard manuscript submission process is based around Omni receiving the manuscript as one file. Some authors may choose to send their manuscript to Omni in several files. The File Merging service is used to merge these files into one document for both editorial services and layout.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.file-merging.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('file-merging', this)\">\n                            <strong style=\"color: #2b2219;\">Submission Tip:</strong> To avoid these fees please adhere to the manuscript submission guidelines.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.file-merging.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('file-merging', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 1 week\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "image-extraction": "<div class=\"image-extraction-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.image-extraction.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('image-extraction', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.image-extraction.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('image-extraction', this)\">\n                          If you choose to submit your manuscript with the images included in the body of your work, Omni must extract these images to properly create a professional layout of your book. The images will be placed back into the manuscript once the layout is complete.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.image-extraction.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('image-extraction', this)\">\n                            <strong style=\"color: #2b2219;\">Interior Layout Protection:</strong> This service will cover the cost of extracting the images to ensure proper interior layout.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.image-extraction.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('image-extraction', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 1-2 weeks\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "resubmission-one-version": "<div class=\"resubmission-one-version-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.resubmission-one-version.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">\n                          Once your book has gone live and is for sale, you can still correct errors or other issues that might have been missed. Choose this service if you only have either a softcover or a hardcover that needs to be updated.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.resubmission-one-version.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">\n                          When a book has gone live and the author finds problems, errors, or other issues that need to be corrected, we can re-submit the file to the printer to update future copies.\n                        </p>\n\n                        <div class=\"p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219;\">\n                            Resubmission Discount:\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.resubmission-one-version.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">\n                            If the author is resubmitting to do a retech, then the price of the retech is reduced when purchased with the resubmission.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Permitted Resubmission Changes:\n                          </h6>\n                          <p class=\"mb-2 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.resubmission-one-version.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">\n                            Authors are able to:\n                          </p>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.resubmission-one-version.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">Make changes to text in galley</li>\n                            <li class=\"editable-field\" data-block-key=\"service.resubmission-one-version.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">Make changes to cover text or design</li>\n                            <li class=\"editable-field\" data-block-key=\"service.resubmission-one-version.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">Change subtitle</li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fff9f0; border: 1px solid #f0dfc8;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #7c5e2a; font-size: 0.9rem; line-height: 1.65;\" data-block-key=\"service.resubmission-one-version.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">\n                            <strong style=\"color: #5c431b;\">Important Policy Notice:</strong> Please remember that the title and the price (Omni bookstore or retail) for a book going through resubmission cannot be changed after it has gone live.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.resubmission-one-version.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">\n                            <strong style=\"color: #2b2219;\">Multiple Formats?</strong> If you have both a paperback and a hardcover version you want to update, please explore our service for <strong>Resubmission (Two Versions)</strong>.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "resubmission-two-version": "<div class=\"resubmission-two-version-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.resubmission-two-version.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">\n                          Choose this service if you have a softcover and hardcover book that needs to be updated.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.resubmission-two-version.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">\n                          When a book has gone live and the author finds problems, errors, or other issues that need to be corrected, we can re-submit the file to the printer to update future copies.\n                        </p>\n\n                        <div class=\"p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219;\">\n                            Resubmission Discount:\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.resubmission-two-version.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">\n                            If the author is resubmitting to do a retech, then the price of the retech is reduced when purchased with the resubmission.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Permitted Resubmission Changes:\n                          </h6>\n                          <p class=\"mb-2 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.resubmission-two-version.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">\n                            Authors are able to:\n                          </p>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.resubmission-two-version.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">Make changes to text in galley</li>\n                            <li class=\"editable-field\" data-block-key=\"service.resubmission-two-version.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">Make changes to cover text or design</li>\n                            <li class=\"editable-field\" data-block-key=\"service.resubmission-two-version.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">Change subtitle</li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fff9f0; border: 1px solid #f0dfc8;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #7c5e2a; font-size: 0.9rem; line-height: 1.65;\" data-block-key=\"service.resubmission-two-version.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">\n                            <strong style=\"color: #5c431b;\">Important Policy Notice:</strong> Please remember that the title and the price (Omni bookstore or retail) for a book going through resubmission cannot be changed after it has gone live.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.resubmission-two-version.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">\n                            <strong style=\"color: #2b2219;\">Single Format?</strong> If your book is available in only one format, such as paperback only or hardcover only, please select our service for <strong>Resubmission (One Version)</strong>.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "bookblast-video-marketing-stand-alone-30days": "<div class=\"bookblast-video-marketing-stand-alone-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                          Go the extra mile with your marketing campaign, and place your video as an ad on YouTube. Seize the opportunity to have your book video introduced as an advertising break before, or in between, YouTube videos.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                          Catch the curiosity and interest of YouTube viewers to increase your reach – and potential book sales. Your book information, purchase, and availability details are displayed directly when the ad is clicked.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            What You Get:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                              A 30-day ad placement campaign on YouTube that gives viewers a preview of your book. Your ad will appear at the beginning of a YouTube video, or in between videos.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                              Interactive viewer engagement: Viewers can get more information about your book by clicking on the video, which redirects them to either your book’s online bookstore page or your personal author website.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-3 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219; font-size: 0.92rem;\">\n                            Prerequisite Notice:\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.9rem; line-height: 1.65;\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                            Please note that you may sign up for this package only if you have purchased either the <strong>Standard Book Video</strong> or <strong>Premium Book Video</strong> service.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.9rem; line-height: 1.65;\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                            <em>*Want to have a longer campaign period? Contact your marketing consultant to get a custom campaign schedule for your video.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "standard-book-video": "<div class=\"standard-book-video-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.standard-book-video.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                          A Standard Book Video helps you create and maintain a meaningful presence online in the competitive marketplace. Video book trailers are an excellent addition to your press releases, social media sites, and author website.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.standard-book-video.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                          By posting your video on social media channels and personal websites, you can reach an influential audience of online video viewers and attract potential readers. Video marketing helps you engage your audience on a visual and emotional level they cannot ignore.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Standard Video Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Creation of a custom-made video book trailer, approximately 45 to 60 seconds in length</li>\n                            <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Storytelling through text, 2-D graphics, motion typography, and high-resolution imagery</li>\n                            <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Distribution of your video to YouTube in order to maximize exposure</li>\n                            <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Full web streaming capability and downloadable master file</li>\n                            <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">100% author rights retention to share with readers, media, friends, and family</li>\n                            <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Review of your video for TV and film consideration by 5 More Minutes</li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219; font-size: 0.92rem;\">\n                            Revisions Policy:\n                          </h6>\n                          <p class=\"mb-2 editable-field\" style=\"color: #57534e; font-size: 0.9rem; line-height: 1.65;\" data-block-key=\"service.standard-book-video.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                            You will be able to make one round of revisions to your video at no additional cost. Acceptable changes include:\n                          </p>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\">\n                            <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Simple text changes and font size adjustments</li>\n                            <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li8\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Corrections or additions to book and author information</li>\n                            <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li9\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Audio level balances and soundtrack adjustments</li>\n                            <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li10\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Author-provided image adjustments</li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219; font-size: 0.94rem;\">\n                            Hollywood TV & Film Consideration (5 More Minutes):\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.9rem; line-height: 1.65;\" data-block-key=\"service.standard-book-video.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                            Once your video is completed, it will be evaluated for television or feature film adaptation by 5 More Minutes, headed by veteran Hollywood executive John Sacchi (former Senior VP at Lionsgate Films). If not selected for immediate production, it is archived into our exclusive Hollywood Database for registered industry producers and directors.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "premium-book-video": "<div class=\"premium-book-video-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.premium-book-video.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                          Give your fans a sensational preview of your book with the Premium Book Video. Complete with professional voiceover, your custom video will enhance your book marketing efforts and make your work stand out.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.premium-book-video.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                          A Premium Book Video provides a cinematic experience that captivates prospective readers. Combining expert narration, sophisticated visual effects, and live-action cinematography, your trailer becomes a cornerstone of your digital marketing.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Premium Video Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Creation of an expanded cinematic video book trailer, approximately 60 to 90 seconds in length</li>\n                            <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Audible storytelling through voiceover narration by a professional voice actor</li>\n                            <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Complex visual design, including 3-D spatial effects, lighting effects, visual filters, and advanced motion graphics</li>\n                            <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Two live-action video clips integrated seamlessly into the trailer</li>\n                            <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Distribution of your video to YouTube to maximize global exposure</li>\n                            <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Web streaming capability with complete author ownership and master file delivery</li>\n                            <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Review of your video for TV and feature film consideration by 5 More Minutes</li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219; font-size: 0.92rem;\">\n                            Revisions Policy:\n                          </h6>\n                          <p class=\"mb-2 editable-field\" style=\"color: #57534e; font-size: 0.9rem; line-height: 1.65;\" data-block-key=\"service.premium-book-video.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                            One round of complimentary revisions is included to ensure complete satisfaction. Acceptable adjustments include:\n                          </p>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\">\n                            <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li8\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Text corrections and typography refinements</li>\n                            <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li9\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Updates to book specifications, awards, and author credentials</li>\n                            <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li10\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Soundtrack and narration audio mixing adjustments</li>\n                            <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li11\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Image updates and asset replacements</li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219; font-size: 0.94rem;\">\n                            Hollywood TV & Film Consideration:\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.9rem; line-height: 1.65;\" data-block-key=\"service.premium-book-video.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                            Your finished trailer is submitted directly to Hollywood production company 5 More Minutes for development consideration, and indexed in our Hollywood Database accessible by entertainment industry decision-makers.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "bookblast-video-marketing-standard": "<div class=\"bookblast-video-marketing-standard-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.bookblast-video-marketing-standard.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-standard', this)\">\n                          The appeal of a book video is undeniable. Make sure your book catches the attention of an engaged audience of online video viewers with the creation of your book video and your YouTube advertising campaign.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.bookblast-video-marketing-standard.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-standard', this)\">\n                          YouTube has over a billion active video viewers watching hundreds of millions of hours of content daily. Bookblast Video Marketing - Standard pairs trailer production with strategic promotion, driving viewers straight to your purchase channels.\n                        </p>\n\n                        <div class=\"p-3.5 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            What You Get:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-standard.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-standard', this)\">One complete Standard Book Video marketing production</li>\n                            <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-standard.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-standard', this)\">A dedicated 30-second campaign version of the Standard Book Video optimized for YouTube advertising</li>\n                            <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-standard.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-standard', this)\">A 30-day ad placement campaign on YouTube that gives viewers a compelling preview of your book</li>\n                            <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-standard.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-standard', this)\">Direct click-through link redirecting viewers to your book’s online bookstore page or personal website</li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "bookblast-video-marketing-premium": "<div class=\"bookblast-video-marketing-premium-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.bookblast-video-marketing-premium.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-premium', this)\">\n                          Strengthen your book’s presence in the marketplace and boost its selling potential by showcasing it on YouTube with a professional voice-narrated video advertising campaign.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.bookblast-video-marketing-premium.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-premium', this)\">\n                          Capture reader curiosity by combining high-end cinematic narration with targeted online advertising. Your campaign reaches audiences with keen interest in your book's genre, turning viewers into active buyers.\n                        </p>\n\n                        <div class=\"p-3.5 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            What You Get:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-premium.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-premium', this)\">One complete Premium Book Video marketing production featuring professional voiceover acting and live-action clips</li>\n                            <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-premium.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-premium', this)\">A specialized 30-second version of your Premium Book Video formatted specifically for YouTube pre-roll and mid-roll placement</li>\n                            <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-premium.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-premium', this)\">A 30-day targeted ad placement campaign on YouTube introducing your book to prospective readers</li>\n                            <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-premium.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-premium', this)\">Seamless interactive click redirection directly to your book’s retail ordering page or author website</li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "15-sec-video-marketing": "<div class=\"fifteen-sec-video-marketing-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.15-sec-video-marketing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">\n                          Advertise your book on a widely-used platform. Get it in front of a huge and engaged audience with uninterrupted short ads on YouTube.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.15-sec-video-marketing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">\n                          With over two billion monthly visitors, YouTube is an unrivaled venue for digital marketing. Short-form video advertising delivers immediate impact, ensuring your book's message is delivered completely before viewers skip.\n                        </p>\n\n                        <div class=\"p-3.5 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            15-Sec Video Marketing Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.15-sec-video-marketing.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">A 15-second custom-made video ad of your book with professional voiceover narration</li>\n                            <li class=\"editable-field\" data-block-key=\"service.15-sec-video-marketing.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">Your video ad shown 350,000 times on YouTube</li>\n                            <li class=\"editable-field\" data-block-key=\"service.15-sec-video-marketing.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">Uninterrupted delivery: Your entire ad plays at the start, midway, or toward the end before the main video continues</li>\n                            <li class=\"editable-field\" data-block-key=\"service.15-sec-video-marketing.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">Custom companion banner of your book linking directly to your ordering page, displayed alongside your video ad on desktop</li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.9rem; line-height: 1.65;\" data-block-key=\"service.15-sec-video-marketing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">\n                            <strong style=\"color: #2b2219;\">Guaranteed Visibility:</strong> Non-skippable short-form placement ensures 100% of your message reaches readers every time.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "video-book-talk": "<div class=\"video-book-talk-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.video-book-talk.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                          Benefit from the rise of online streaming services with a video interview about your book and writing process, streamed on Roku, Amazon Fire TV, and top podcast networks.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.video-book-talk.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                          Your book shouldn't be confined to a box, whether that's your bookshelf, a storage container, or the four walls of traditional media. Ride the streaming wave with Roku's 70M+ users, Amazon Fire TV's 50M+ users, and YouTube's 1B+ audience to connect with readers in a fresh, conversational format.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Video Book Talk Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.video-book-talk.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                              <strong>Video Interview on the <em>Talking Books</em> Show:</strong> A pre-recorded 15-20 minute in-depth interview with British author and host JT Crowley. Streamed across top platforms including Roku, Amazon Fire TV, YouTube, ExpertsandAuthors.tv, and WebTalkRadio.net.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.video-book-talk.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                              <strong>Audio Podcast Distribution:</strong> An audio-only podcast version available on Apple Podcasts, Spotify, iHeartRadio, and major aggregators worldwide.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.video-book-talk.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                              <strong>Social Media Promotion:</strong> Dedicated social media spotlight featuring your interview across active community channels.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.video-book-talk.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                              <strong>Promotional Asset Delivery:</strong> A shareable link and video asset to embed on your website and use throughout your promotional campaigns.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219; font-size: 0.92rem;\">\n                            About Host JT Crowley:\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.9rem; line-height: 1.65;\" data-block-key=\"service.video-book-talk.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                            JT Crowley is a British author whose global adventures and storytelling passion shape every interview. Join him on <em>Talking Books</em> as he dives deep with authors into the inspiration and craft behind their stories.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "indie-book-review-bundle": "<div class=\"indie-book-review-bundle-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.indie-book-review-bundle.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                          As a self-published author in the competitive literary industry, securing as many book reviews as you can get helps you stand out. Partner with the pros at BookLife by Publishers Weekly.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.indie-book-review-bundle.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                          BookLife is a website created by <em>Publishers Weekly</em> that focuses on supporting independent authors. The Indie Book Review Bundle gives you a comprehensive review crafted by professional <em>Publishers Weekly</em> reviewers under the BookLife Reviews brand, paired with high-impact industry marketing campaigns.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Extensive BookLife Review Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.indie-book-review-bundle.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                              <strong>Comprehensive 300-Word Review:</strong> Covers plot summary, critique, and in-depth analysis of your book, including an assessment of target readership.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.indie-book-review-bundle.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                              <strong>One-Sentence Takeaway:</strong> An honest, positive headline takeaway summarizing the reviewer's opinion of your book's best aspects.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.indie-book-review-bundle.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                              <strong>Comparison (Comp) Titles & Authors:</strong> Strategic list of comparable books and authors for commercial positioning.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.indie-book-review-bundle.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                              <strong>Production Letter Grades (A+ to C):</strong> Objective grading across five production elements: cover art, interior design and typography, illustrations, editing, and marketing copy.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Digital & Print Advertising Campaigns:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.indie-book-review-bundle.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                              <strong>PublishersWeekly.com Banner Ad:</strong> 10,000 guaranteed impressions across PublishersWeekly.com, which reaches over 14 million annual unique visitors.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.indie-book-review-bundle.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                              <strong>Publishers Weekly Supplement Ad (1 of 8 slot):</strong> Your book ad appears in an official stand-alone conference supplement (e.g. Winter Institute, Children’s Institute, Star Watch, or AAR & SBL) and is center-stitched to the print magazine reaching 68,000 subscribers.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.indie-book-review-bundle.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                              <strong>Database Archiving:</strong> Review submitted to major book trade databases including EBSCO, Ingram, and ProQuest, accessible to bookstores and libraries globally.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.indie-book-review-bundle.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                            <em>*Guidelines: Suitable for English-language books up to 150,000 words that are commercially available in the US. Author maintains complete publishing control on BookLife.com.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "literary-gateway-bundle": "<div class=\"literary-gateway-bundle-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.literary-gateway-bundle.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                          With Literary Gateway, get a mix of services designed to put you at the forefront of award opportunities to help build your author brand.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.literary-gateway-bundle.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                          A book award is more than a feather in your cap—it makes books noticeably more valuable in the eyes of consumers, media, and retailers. Omni simplifies award matching and submission while securing professional editorial praise for your title.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Literary Gateway Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.literary-gateway-bundle.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                              <strong>6 Months Access to Awards Finder:</strong> Intelligent award-matching platform identifying 1 award opportunity weekly (24+ opportunities). Each month, Awards Finder selects the best match, prepares your nomination package, and handles entry submission on your behalf.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.literary-gateway-bundle.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                              <strong>Objective BlueInk Review:</strong> A 250–300 word professional critique by BlueInk Review—founded by an internationally known literary agent and an award-winning review editor to celebrate the best of independent publishing.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.literary-gateway-bundle.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                              <strong>BookMad Magazine Feature Eligibility:</strong> Award-winning titles are eligible for a spotlight feature in BookMad Magazine and announced across official social media pages.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.literary-gateway-bundle.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                              <strong>Cover Resubmission Included:</strong> Free cover revision to proudly integrate your review pull quotes and/or official award seals.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "review-duo": "<div class=\"review-duo-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.review-duo.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                          Spark readers’ interest and build credibility for your book with the Review Duo service. Receive professional, unbiased assessments from two esteemed industry review platforms.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.review-duo.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                          Reviews from trusted industry professionals establish essential social proof for your title across retail and distribution channels.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Review Duo Package Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.review-duo.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                              <strong>Pacific Book Review (PBR):</strong> Authoritative, objective critique written by specialists selected for their genre expertise, circulated to industry professionals via monthly newsletter and social networks.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.review-duo.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                              <strong>The US Review of Books (USRB):</strong> Professional review introduced to more than 14,000 subscribers in the USRB monthly newsletter and showcased on their website.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.review-duo.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                              <strong>Entry to the Eric Hoffer Award:</strong> Entry to one of the most prestigious independent book awards recognizing salient writing and small-publisher spirit.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.review-duo.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                              <strong>Entry to the Pacific Book Awards:</strong> Celebrates outstanding excellence across print and electronic literature.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.review-duo.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                              <strong>Free Cover Revision Option:</strong> Update your cover layout to incorporate excerpted review quotes at no additional charge.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.review-duo.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                            <em>Please Note: If a returned review is unfavorable, you may choose not to use it in your promotional materials; review service fees are non-refundable.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "review-duo-plus": "<div class=\"review-duo-plus-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.review-duo-plus.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                          Spark readers’ interest and build credibility for your book with the Review Duo Plus service, featuring dual authoritative reviews, two award entries, and a syndicated radio broadcast.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.review-duo-plus.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                          Review Duo Plus builds upon our popular review package by adding premier digital visibility and syndicated audio broadcast reach.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Review Duo Plus Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.review-duo-plus.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                              <strong>Pacific Book Review (PBR):</strong> Objective, specialist review promoted across industry networks and monthly newsletters.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.review-duo-plus.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                              <strong>The US Review of Books (USRB):</strong> Review sent to 14,000+ newsletter subscribers plus <strong>one month featured placement</strong> in the Featured Book Reviews section of USRB.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.review-duo-plus.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                              <strong>10-15 Minute Online Radio Interview:</strong> Syndicated broadcast via iTunes and Toginet.com, available for download on mobile devices and repurposing across your author marketing.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.review-duo-plus.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                              <strong>Entry to the Eric Hoffer Award:</strong> Official nomination for the prestigious Hoffer Award.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.review-duo-plus.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                              <strong>Entry to the Pacific Book Awards:</strong> Official nomination celebrating excellence in modern publishing.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.review-duo-plus.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                              <strong>Free Cover Revision:</strong> Complimentary cover redesign to include review pull quotes and award honors.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.review-duo-plus.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                            <em>Please Note: If a returned review is unfavorable, you may choose not to use it in your promotional materials; review service fees are non-refundable.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "the-trifecta-review-service": "<div class=\"the-trifecta-review-service-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.the-trifecta-review-service.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                          Get unbiased and professional reviews from three esteemed publications. With the Omni Trifecta Review Service, your marketing efforts receive an elite boost in the competitive marketplace.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.the-trifecta-review-service.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                          A review can profoundly influence the market’s awareness toward your book. The Trifecta Review Service brings together three of the most influential authorities in the literary review landscape.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            The Three Esteemed Reviews:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.the-trifecta-review-service.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                              <strong>Kirkus Indie:</strong> Among the world’s most acclaimed and authoritative book review providers, delivering honest, fair, and respected critiques that open doors to bookstore shelves and media attention.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.the-trifecta-review-service.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                              <strong>Clarion Review-for-Fee:</strong> ForeWord Magazine’s prestigious review service that heavily influences buying decisions of booksellers and public librarians across the country.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.the-trifecta-review-service.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                              <strong>BlueInk Review:</strong> Founded by an internationally respected literary agent and an award-winning book review editor to provide honest, vetting-driven reviews exclusively for independent authors.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Print Magazine Placement & Cover Update:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.the-trifecta-review-service.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                              <strong>Kirkus Reviews Magazine (1 of 8 slot):</strong> National print visibility with a black-and-white advertisement inside the pages of <em>Kirkus Reviews</em> magazine.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.the-trifecta-review-service.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                              <strong>Complimentary Cover Revision:</strong> Update your cover layout to feature excerpts from your reviews at no additional cost.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.the-trifecta-review-service.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                            <em>Please Note: If a returned review is unfavorable, the author can choose not to use it in marketing efforts; review fees are non-refundable.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "join-the-la-times-festival-of-books-2025": "<div class=\"la-times-festival-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.join-the-la-times-festival-of-books-2025.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('join-the-la-times-festival-of-books-2025', this)\">\n                          Get ready to celebrate the 30th anniversary of the L.A. Times Festival of Books on April 26–27, 2025 at the University of Southern California campus in Los Angeles.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.join-the-la-times-festival-of-books-2025.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('join-the-la-times-festival-of-books-2025', this)\">\n                          The Los Angeles Times Festival of Books is one of the largest and most prestigious book festivals in the United States, attracting more than 150,000 booklovers and media members each year. Since its debut in 1996, the festival has joined literature lovers with hundreds of booksellers, publishers, and literary organizations. The LA Times Festival of Books 2025 is your chance to meet face-to-face with potential readers and promote your book at this major industry event.\n                        </p>\n\n                        <div class=\"row g-3 mb-4\">\n                          <div class=\"col-md-6\">\n                            <div class=\"p-3 rounded-3 h-100\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                              <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.94rem;\">\n                                <i class=\"bi bi-calendar-event me-2 text-warning\"></i>Event Information\n                              </h6>\n                              <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\">\n                                <li class=\"editable-field\" data-block-key=\"service.join-the-la-times-festival-of-books-2025.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('join-the-la-times-festival-of-books-2025', this)\"><strong>Occasion:</strong> 30th Anniversary Celebration</li>\n                                <li class=\"editable-field\" data-block-key=\"service.join-the-la-times-festival-of-books-2025.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('join-the-la-times-festival-of-books-2025', this)\"><strong>Dates:</strong> April 26–27, 2025</li>\n                                <li class=\"editable-field\" data-block-key=\"service.join-the-la-times-festival-of-books-2025.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('join-the-la-times-festival-of-books-2025', this)\"><strong>Location:</strong> University of Southern California (USC) Campus, Los Angeles, CA</li>\n                                <li class=\"editable-field\" data-block-key=\"service.join-the-la-times-festival-of-books-2025.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('join-the-la-times-festival-of-books-2025', this)\"><strong>Audience:</strong> 150,000+ avid readers, authors, publishers, and media members</li>\n                              </ul>\n                            </div>\n                          </div>\n                          <div class=\"col-md-6\">\n                            <div class=\"p-3 rounded-3 h-100\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                              <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.94rem;\">\n                                <i class=\"bi bi-geo-alt me-2 text-warning\"></i>Major Industry Event\n                              </h6>\n                              <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.join-the-la-times-festival-of-books-2025.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('join-the-la-times-festival-of-books-2025', this)\">\n                                A premier cultural gathering since 1996, uniting readers, independent authors, national retailers, and literary tastemakers in the heart of Southern California.\n                              </p>\n                            </div>\n                          </div>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Participation Options Available:\n                          </h6>\n                          <div class=\"d-flex flex-column gap-3\">\n                            <div class=\"p-3 rounded-2\" style=\"background: #ffffff; border: 1px solid #ebd9c4;\">\n                              <strong class=\"d-block mb-1\" style=\"color: #2b2219; font-size: 0.92rem;\">\n                                <i class=\"bi bi-book me-2 text-warning\"></i>Author Solutions Bookstore Gallery\n                              </strong>\n                              <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.6;\" data-block-key=\"service.join-the-la-times-festival-of-books-2025.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('join-the-la-times-festival-of-books-2025', this)\">\n                                Showcase your book for crowds of avid readers to discover by displaying it in the official Bookstore Gallery throughout the two-day festival. Attendees can browse, examine your book, and purchase copies on-site.\n                              </p>\n                            </div>\n\n                            <div class=\"p-3 rounded-2\" style=\"background: #ffffff; border: 1px solid #ebd9c4;\">\n                              <strong class=\"d-block mb-1\" style=\"color: #2b2219; font-size: 0.92rem;\">\n                                <i class=\"bi bi-pen me-2 text-warning\"></i>Live Author Book Signing\n                              </strong>\n                              <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.6;\" data-block-key=\"service.join-the-la-times-festival-of-books-2025.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('join-the-la-times-festival-of-books-2025', this)\">\n                                Be the star of your own book signing at the Author Solutions booth. Engage directly with book lovers, answer questions, pose for photos, and personalize autographs for your readers.\n                              </p>\n                            </div>\n                          </div>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.join-the-la-times-festival-of-books-2025.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('join-the-la-times-festival-of-books-2025', this)\">\n                            <em>*Notice: Contact your marketing consultant to find out more about these options. Spots will be filled on a first-come, first-served basis, so don't wait.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "hollywood-coverage": "<div class=\"hollywood-coverage-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.hollywood-coverage.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-coverage', this)\">\n                          If you’ve ever wondered—even for a moment—if your book could be turned into a movie, Hollywood Coverage is the most cost-effective service that will help you answer that question.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.hollywood-coverage.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-coverage', this)\">\n                          A professional reader will develop your book’s coverage, the standard evaluation format used across the movie and television industry. Coverage provides studio executives, producers, and literary agents with a clear, concise appraisal of your story’s cinematic viability.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Your Hollywood Coverage Elements:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-coverage.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-coverage', this)\">\n                              <strong>Thorough Synopsis:</strong> Highlights the main characters, pivotal plot points, dramatic arc, and major events in your story.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-coverage.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-coverage', this)\">\n                              <strong>Critical Analysis:</strong> Professional evaluation addressing key story mechanics, thematic resonance, character development, and specific recommendations on how your manuscript can be adapted for the screen.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Studio Consideration & Database Placement:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-coverage.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-coverage', this)\">\n                              <strong>5 More Minutes First-Look Consideration:</strong> Once completed, your coverage is submitted to our first-look production partner, 5 More Minutes, led by veteran studio executive John Sacchi. If interested, they will reach out directly to discuss potential adaptation.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-coverage.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-coverage', this)\">\n                              <strong>Hollywood Database Access:</strong> If 5 More Minutes chooses not to option your project, your coverage is archived into our exclusive Hollywood Database where certified directors, producers, actors, and agents actively scout for fresh literary concepts.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219; font-size: 0.92rem;\">\n                            About 5 More Minutes & John Sacchi:\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.hollywood-coverage.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-coverage', this)\">\n                            5 More Minutes is a full-service production shingle run by veteran Hollywood executive John Sacchi, who spent 15 years as a senior production and development executive at Lionsgate Films. His career credits include <em>Akeelah and the Bee</em>, <em>Confidence</em>, <em>Employee of the Month</em>, <em>The Possession</em>, <em>Punisher</em>, as well as current adaptations like Lionsgate’s <em>Dork Diaries</em> and <em>Rogues Gallery</em>.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.hollywood-coverage.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-coverage', this)\">\n                            <em>*Your Hollywood Coverage will be fulfilled by an independent industry professional who conducts evaluations for major agencies and studios. Omni Virtual Solutions has no input regarding the critical analysis and cannot guarantee specific option results.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "hollywood-treatment": "<div class=\"hollywood-treatment-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.hollywood-treatment.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-treatment', this)\">\n                          Your book has all the elements Hollywood wants—an exciting plot, well-developed characters, and fresh content—yet there’s still a crucial piece you need in order to be taken seriously by established entertainment executives: a professional treatment.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.hollywood-treatment.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-treatment', this)\">\n                          A treatment is a thoroughly developed guide that outlines how a screenwriter would adapt your book into a fully-developed screenplay. As the framework used to transform your work into another medium, Hollywood Treatment is the essential first step to drafting a screenplay. By defining exactly how a screenwriter will approach the adaptation, you give agents, studios, and producers a direct shortcut to the cinematic essence of your book.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            How Hollywood Treatment Works:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-treatment.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-treatment', this)\">\n                              <strong>Screenwriter Matching:</strong> We match you with an experienced professional screenwriter from our industry network whose background best complements your book’s genre and voice.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-treatment.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-treatment', this)\">\n                              <strong>Comprehensive 5 to 10-Page Treatment:</strong> Your screenwriter crafts a detailed treatment outlining the three-act structure, scene progressions, and character dynamics tailored for feature film or television.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-treatment.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-treatment', this)\">\n                              <strong>100% Rights & Story Ownership:</strong> The screenwriter waives all rights to the treatment, ensuring you maintain full, complete ownership of your story and conceptual property.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Studio Consideration & Database Placement:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-treatment.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-treatment', this)\">\n                              <strong>5 More Minutes First Look:</strong> Upon completion, your treatment is submitted to our first-look partner, 5 More Minutes (headed by veteran Lionsgate executive John Sacchi), for TV or film adaptation consideration.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-treatment.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-treatment', this)\">\n                              <strong>Exclusive Hollywood Database:</strong> If 5 More Minutes does not engage with your concept, your treatment is uploaded to our secure Hollywood Database accessible by entertainment industry producers, directors, agents, and writers.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.hollywood-treatment.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-treatment', this)\">\n                            <em>*Please Note: Hollywood Treatment provides an adaptation blueprint based on your book. Details in plot, pacing, and characters may be adjusted to fit cinematic storytelling. Please do not attempt to contact 5 More Minutes directly, as unauthorized inquiries will result in immediate disqualification from consideration.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "hollywood-screenplay": "<div class=\"hollywood-screenplay-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.hollywood-screenplay.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-screenplay', this)\">\n                          Don't just dream about it—take action. If you’re determined to turn your book into a movie or television series, a screenplay is the way to get noticed by Hollywood executives.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.hollywood-screenplay.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-screenplay', this)\">\n                          A screenplay is a fully fleshed out script that television and movie producers use to evaluate whether an adaptation of your book is something they want to produce. With a professionally adapted screenplay, you make the ultimate marketing push into the entertainment business and demonstrate that your story is production-ready.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Full Screenplay Adaptation Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-screenplay.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-screenplay', this)\">\n                              <strong>Script Adapted from Approved Treatment:</strong> A seasoned industry screenwriter crafts a feature-length or television pilot script adhering strictly to your approved Hollywood Treatment.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-screenplay.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-screenplay', this)\">\n                              <strong>Dialogue & Dramatic Action:</strong> Fully formatted script with authentic character dialogue, scene transitions, dramatic tension, and atmospheric scene descriptions meeting Hollywood studio standards.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-screenplay.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-screenplay', this)\">\n                              <strong>Complete Author Ownership:</strong> The screenwriter waives all copyright and writing rights to the screenplay; you retain 100% intellectual property ownership.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Hollywood Studio Evaluation & Database Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-screenplay.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-screenplay', this)\">\n                              <strong>5 More Minutes First Look:</strong> Your completed script is delivered directly to John Sacchi’s production shingle, 5 More Minutes, for adaptation consideration.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.hollywood-screenplay.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-screenplay', this)\">\n                              <strong>Exclusive Hollywood Database:</strong> If 5 More Minutes decides not to acquire your screenplay, it is entered into our industry database accessible to verified producers, directors, agents, and studio representatives.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.hollywood-screenplay.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hollywood-screenplay', this)\">\n                            <em>*Prerequisite Notice: An approved Hollywood Treatment is a required prerequisite for Hollywood Screenplay. Please speak with your consultant if you have not yet completed a treatment. Please do not attempt to contact 5 More Minutes directly.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "sem-1000-clicks": "<div class=\"sem-1000-clicks-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.sem-1000-clicks.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-1000-clicks', this)\">\n                          The digital age gives you the power of immediate connection. Attract potential readers and drive guaranteed visitors directly to your website with Google Search Engine Marketing.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.sem-1000-clicks.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-1000-clicks', this)\">\n                          With our SEM service, you can attract potential readers and drive high-intent traffic to your website with the help of the world's leading search engine. Your ad will be strategically placed on Google search result pages when readers query words and phrases related to your book's themes and genre.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Campaign Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.sem-1000-clicks.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-1000-clicks', this)\">\n                              <strong>1,000 Guaranteed Clicks:</strong> High-intent web users delivered directly to the author landing page or retail website of your choice.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.sem-1000-clicks.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-1000-clicks', this)\">\n                              <strong>Up to 20 Tailored Keywords:</strong> Selection of up to 20 strategic search keywords and phrases aligned with your book’s genre and audience.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.sem-1000-clicks.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-1000-clicks', this)\">\n                              <strong>Comprehensive Analytics Reporting:</strong> Detailed post-campaign reporting showing individual keyword performance, click-through metrics, and traffic volume to inform future marketing.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "social-media-30-day-content-plan": "<div class=\"social-content-plan-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.social-media-30-day-content-plan.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-content-plan', this)\">\n                          Ready to ignite a dynamic conversation about your book's release? Our 30-Day Social Media Content Schedule provides turnkey collateral for each day leading up to your big launch.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.social-media-30-day-content-plan.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-content-plan', this)\">\n                          Building a social media identity that encapsulates your book demands both time and expertise. This service delivers ready-made visual assets, compelling captions, and strategic roadmaps so you can focus entirely on your writing.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Content Schedule Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-30-day-content-plan.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-content-plan', this)\">\n                              <strong>Weekly Goals:</strong> Scheduled milestones that dovetail with your promotional timeline to generate escalating curiosity.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-30-day-content-plan.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-content-plan', this)\">\n                              <strong>Daily Visuals & Graphics:</strong> Professionally designed custom graphics for all 30 days capturing your book’s unique branding.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-30-day-content-plan.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-content-plan', this)\">\n                              <strong>Engaging Captions:</strong> Compelling post copy with intuitive calls-to-action crafted to spark comments, shares, and reader connections.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-30-day-content-plan.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-content-plan', this)\">\n                              <strong>Book Snippets & Teasers:</strong> Highlight the most enticing passages of your story paired with striking visual cards.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-30-day-content-plan.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-content-plan', this)\">\n                              <strong>Hashtag Selection & Caption Guidance:</strong> Curated hashtag recommendations and personalization advice to expand discoverability.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-30-day-content-plan.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-content-plan', this)\">\n                              <strong>Engagement Strategies:</strong> Proven conversational prompts and community-building techniques.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.social-media-30-day-content-plan.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-content-plan', this)\">\n                            <em>*Note: This service delivers complete creative collateral and scheduling; it does not cover manual account posting or daily management.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "social-media-30-day-strategy": "<div class=\"social-strategy-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.social-media-30-day-strategy.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-strategy', this)\">\n                          Maximize the impact and visibility of your book with our 30-Day Social Media Strategy—a step-by-step weekly plan rich with creative content suggestions and hashtags.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.social-media-30-day-strategy.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-strategy', this)\">\n                          Ideal for authors launching a debut novel, revitalizing a backlist title, or preparing a sequel. We equip you with a magnetic content roadmap reflecting the latest social media trends.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Strategic Framework Elements:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-30-day-strategy.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-strategy', this)\">\n                              <strong>Targeted Weekly Goals:</strong> Structured roadmap setting early anticipation and accelerating reader interest toward launch day.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-30-day-strategy.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-strategy', this)\">\n                              <strong>Daily Content Ideas:</strong> Individually crafted concepts showcasing story themes, character backstories, and behind-the-scenes insights.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-30-day-strategy.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-strategy', this)\">\n                              <strong>Bespoke Hashtag Guidance:</strong> Genre-specific hashtag recommendations to reach enthusiastic reader demographics across platforms.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-30-day-strategy.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-strategy', this)\">\n                              <strong>Audience Engagement Techniques:</strong> Practical techniques to cultivate conversations and convert casual followers into loyal readers.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.social-media-30-day-strategy.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-30-day-strategy', this)\">\n                            <em>*Note: This strategy provides planning, calendars, and textual prompts; graphical design and individual post uploads are not included.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "kirkus-title-express": "<div class=\"kirkus-title-express-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.kirkus-title-express.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('kirkus-title-express', this)\">\n                          Collaborating with a revered literary authority like Kirkus Reviews provides instant credibility and global reach for your online giveaway campaign.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.kirkus-title-express.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('kirkus-title-express', this)\">\n                          Founded in 1933, Kirkus Reviews garners 2.6 million monthly website impressions and 65,000 email subscribers. Kirkus Title Express embeds your book into an official Kirkus online giveaway with full promotional support.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Service Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.kirkus-title-express.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('kirkus-title-express', this)\">\n                              <strong>Two-Week Online Giveaway:</strong> Prominent listing inside Kirkus’s curated Online Giveaways section.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.kirkus-title-express.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('kirkus-title-express', this)\">\n                              <strong>100 Digital BookStub™ Codes:</strong> Secure download codes allowing 100 readers to claim a complimentary digital copy of your e-book.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.kirkus-title-express.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('kirkus-title-express', this)\">\n                              <strong>Homepage & Newsletter Ad:</strong> Standard side box advertisement on the Kirkus.com homepage and featured in one issue of Kirkus's <em>Critic’s Picks</em> email newsletter.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "online-booksellers-advertising": "<div class=\"online-booksellers-advertising-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.online-booksellers-advertising.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-booksellers-advertising', this)\">\n                          Put your book in front of consumer readers on Amazon and professional trade buyers on Ingram's ipage platform.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.online-booksellers-advertising.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-booksellers-advertising', this)\">\n                          Cover the most critical book-marketing ground by advertising across both consumer and trade retail hubs. Amazon reaches 181 million monthly unique visitors, while Ingram's ipage is accessed daily by over 50,000 retailers, librarians, and educators.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Dual-Channel Advertising Elements:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.online-booksellers-advertising.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-booksellers-advertising', this)\">\n                              <strong>Banner Ad Campaign on Amazon:</strong> Showcase your book cover in a targeted banner ad delivering 500,000 guaranteed impressions across Amazon.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.online-booksellers-advertising.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-booksellers-advertising', this)\">\n                              <strong>Banner Ad Campaign on Ingram’s ipage:</strong> Featured cover placement on a specialized title landing page with a two-week accompanying banner ad on ipage, directly reaching retail booksellers and institutional acquisitions staff.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.online-booksellers-advertising.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-booksellers-advertising', this)\">\n                            <em>*Requirements: Best suited for books available in both paperback and ebook formats; title must be listed as returnable in the Ingram distribution catalog.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "e-book-promo-venture-30-days": "<div class=\"ebook-promo-venture-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.e-book-promo-venture-30-days.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('e-book-promo-venture-30-days', this)\">\n                          Tap into the excitement of bargain book sales. Mark down your Kindle edition for a limited promotional window and amplify discoverability with BookBub and Facebook.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.e-book-promo-venture-30-days.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('e-book-promo-venture-30-days', this)\">\n                          Discount promotions trigger massive downloading velocity and improve sales ranking. We coordinate the price adjustment and deliver 30 days of continuous exposure to enthusiastic readers.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Venture Package Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.e-book-promo-venture-30-days.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('e-book-promo-venture-30-days', this)\">\n                              <strong>Kindle Promotional Price Markdown:</strong> Coordinated limited-time discount on Amazon to drive rapid reader adoption.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.e-book-promo-venture-30-days.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('e-book-promo-venture-30-days', this)\">\n                              <strong>BookBub Daily Email Campaign (30 Days):</strong> Placement of your book ad in BookBub’s daily recommendation blasts reaching millions of subscriber inboxes.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.e-book-promo-venture-30-days.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('e-book-promo-venture-30-days', this)\">\n                              <strong>Facebook Genre Ad Campaign (30 Days):</strong> Your ebook ad featured alongside genre titles on Facebook for 30 consecutive days.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "e-book-promo-launcher": "<div class=\"ebook-promo-launcher-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.e-book-promo-launcher.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('e-book-promo-launcher', this)\">\n                          Triple-channel promotional power: combine a limited-time Kindle markdown with 30 days of continuous advertising across BookBub, Facebook, and Amazon.com.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.e-book-promo-launcher.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('e-book-promo-launcher', this)\">\n                          The Launcher package expands on our popular promo venture by putting your promotional bargain ad directly on the storefront of the world's largest online bookseller.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Launcher Package Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.e-book-promo-launcher.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('e-book-promo-launcher', this)\">\n                              <strong>Kindle Promotional Markdown:</strong> Coordinated limited-time promotional pricing on Amazon.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.e-book-promo-launcher.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('e-book-promo-launcher', this)\">\n                              <strong>BookBub Daily Email Campaign (30 Days):</strong> Featured ad placement in BookBub's daily email blasts.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.e-book-promo-launcher.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('e-book-promo-launcher', this)\">\n                              <strong>Facebook Targeted Ad Campaign (30 Days):</strong> Genre-targeted ad rotation reaching active mobile and desktop readers.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.e-book-promo-launcher.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('e-book-promo-launcher', this)\">\n                              <strong>Amazon.com Direct Ad Placement (30 Days):</strong> Premium banner ad placement running natively on Amazon.com for 30 full days.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "social-media-advertising-basic": "<div class=\"social-ad-basic-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.social-media-advertising-basic.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-basic', this)\">\n                          Put your book directly in front of targeted readers on Facebook and Instagram with at least 1 million guaranteed impressions.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.social-media-advertising-basic.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-basic', this)\">\n                          Cut through online clutter with precise demographic and interest targeting across the world's most engaged social networks.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Basic Package Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-advertising-basic.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-basic', this)\">\n                              <strong>Custom Target Audience:</strong> Tailored segmentation identifying potential readers interested in your genre, comparable authors, and subject matter.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-advertising-basic.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-basic', this)\">\n                              <strong>At Least 1 Million Impressions:</strong> Image ad displayed over 1,000,000 times in newsfeeds across Facebook and Instagram mobile.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-advertising-basic.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-basic', this)\">\n                              <strong>Campaign Monitoring & Optimization:</strong> Ongoing monitoring and campaign management by Omni digital marketing specialists.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "social-media-advertising-essential": "<div class=\"social-ad-essential-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.social-media-advertising-essential.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-essential', this)\">\n                          Double your reach with multimedia storytelling: image and short video ads displayed at least 2 million times across Facebook and Instagram.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.social-media-advertising-essential.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-essential', this)\">\n                          Video content evokes emotion and drives significantly higher engagement rates. The Essential package combines high-converting image creatives with dynamic video ads.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Essential Package Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-advertising-essential.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-essential', this)\">\n                              <strong>Custom Targeted Audience:</strong> Granular audience curation tailored to match readers seeking new books in your genre.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-advertising-essential.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-essential', this)\">\n                              <strong>Dual Creative Formats:</strong> Both a custom image ad and a dynamic short video ad created for your book.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-advertising-essential.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-essential', this)\">\n                              <strong>At Least 2 Million Impressions:</strong> Minimum 2,000,000 verified impressions across Facebook and Instagram feeds.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-advertising-essential.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-essential', this)\">\n                              <strong>End-to-End Ad Campaign Management:</strong> Complete budget optimization, delivery tracking, and campaign oversight.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "social-media-advertising-advanced": "<div class=\"social-ad-advanced-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.social-media-advertising-advanced.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-advanced', this)\">\n                          Our most robust social advertising campaign: image, video, and interactive mobile ads delivered at least 4 million times across Facebook, Instagram, and the Audience Network.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.social-media-advertising-advanced.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-advanced', this)\">\n                          Expand beyond traditional newsfeeds into thousands of high-traffic mobile applications via Facebook’s Audience Network, surrounding your audience with engaging multi-format creatives.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Advanced Package Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-advertising-advanced.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-advanced', this)\">\n                              <strong>Custom Reader Audience:</strong> Deep-level behavioral and interest targeting to reach passionate book buyers.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-advertising-advanced.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-advanced', this)\">\n                              <strong>Three High-Impact Ad Formats:</strong> Custom image ad, engaging short video ad, and interactive mobile canvas ad.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-advertising-advanced.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-advanced', this)\">\n                              <strong>At Least 4 Million Impressions:</strong> Massive distribution across Facebook, Instagram, and Facebook Audience Network apps.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.social-media-advertising-advanced.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('social-media-advertising-advanced', this)\">\n                              <strong>Dedicated Management & Monitoring:</strong> Professional ad management from setup to campaign completion.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "display-advertising-on-google-30-days-package": "<div class=\"google-display-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.display-advertising-on-google-30-days-package.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('display-advertising-on-google-30-days-package', this)\">\n                          Consumers spend 95% of their online time exploring websites and content that interest them. Put your book on the Google Display Network across up to 2 million partner sites.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.display-advertising-on-google-30-days-package.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('display-advertising-on-google-30-days-package', this)\">\n                          Your book ad is showcased across high-authority websites including YouTube, Gmail, Blogger, and Google Finance, as well as literary blogs and news outlets.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Display Package Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.display-advertising-on-google-30-days-package.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('display-advertising-on-google-30-days-package', this)\">\n                              <strong>Choice of Ad Formats:</strong> Responsive image with text, text-only, or multi-format display creatives.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.display-advertising-on-google-30-days-package.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('display-advertising-on-google-30-days-package', this)\">\n                              <strong>30-Day Targeted Placement:</strong> Continuous ad presence across partner websites on the vast Google Display Network.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.display-advertising-on-google-30-days-package.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('display-advertising-on-google-30-days-package', this)\">\n                              <strong>Precision Demographic Targeting:</strong> Filter by geographic location, age, language, audience interests, reading topics, and relevant keywords.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.display-advertising-on-google-30-days-package.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('display-advertising-on-google-30-days-package', this)\">\n                              <strong>Bandwidth Coverage Included:</strong> Up to 10 GB of excess monthly bandwidth supported when using your Omni-designed author website as the destination landing page.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "sem-advanced-campaign": "<div class=\"sem-advanced-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.sem-advanced-campaign.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-advanced-campaign', this)\">\n                          With millions of Google searches made every minute, seize the opportunity to capture high-intent readers with 3 months of premium first-page search ad placement.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.sem-advanced-campaign.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-advanced-campaign', this)\">\n                          When readers search for themes, topics, and genres related to your book, your ad appears prominently on the first page of Google search results—driving visitors directly to your custom author website.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Advanced Campaign Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.sem-advanced-campaign.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-advanced-campaign', this)\">\n                              <strong>3 Months Online Ad Presence:</strong> Sustained quarterly campaign driving steady organic-quality visitors to your book.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.sem-advanced-campaign.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-advanced-campaign', this)\">\n                              <strong>First-Page Google Search Placement:</strong> High-visibility top-of-page search ad positioning for relevant keyword queries.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.sem-advanced-campaign.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-advanced-campaign', this)\">\n                              <strong>Up to 30 Managed Keywords:</strong> In-house search engine marketing experts curate, test, and manage up to 30 targeted keywords.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.sem-advanced-campaign.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-advanced-campaign', this)\">\n                              <strong>Monthly Strategy & Reporting:</strong> In-depth monthly performance reports with agile keyword tuning based on live search trends.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.sem-advanced-campaign.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-advanced-campaign', this)\">\n                              <strong>Deluxe Author Website Setup:</strong> A custom-designed author website to serve as your brand headquarters and high-converting landing destination.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "sem-specialist-campaign": "<div class=\"sem-specialist-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.sem-specialist-campaign.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-specialist-campaign', this)\">\n                          Our premier Google search engine marketing campaign: 5 months of first-page placement, up to 50 tracked keywords, bi-weekly analytics, and a website with an integrated author blog.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.sem-specialist-campaign.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-specialist-campaign', this)\">\n                          The Specialist Campaign delivers maximum Google reach and proactive search dominance over a five-month span, paired with bi-weekly optimization meetings to keep you at the helm of your digital growth.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Specialist Campaign Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.sem-specialist-campaign.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-specialist-campaign', this)\">\n                              <strong>5 Months Premier Ad Presence:</strong> Extended multi-month campaign establishing dominant visibility on Google.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.sem-specialist-campaign.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-specialist-campaign', this)\">\n                              <strong>First-Page Placement Throughout:</strong> Your book ads consistently show on page 1 of Google search results for target queries.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.sem-specialist-campaign.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-specialist-campaign', this)\">\n                              <strong>Up to 50 Curated Keywords:</strong> Expanded keyword spectrum researched and optimized by senior search specialists.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.sem-specialist-campaign.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-specialist-campaign', this)\">\n                              <strong>Bi-Weekly Reporting & Proactive Refinement:</strong> Frequent progress reviews and rapid campaign tuning every two weeks.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.sem-specialist-campaign.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('sem-specialist-campaign', this)\">\n                              <strong>Premier Website Design with Blog:</strong> Full author website setup including a dedicated blogging system to regularly update readers on your writing, events, and releases.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "author-website-setup": "<div class=\"author-website-setup-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.author-website-setup.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">\n                          Reach out to a worldwide audience with Omni's Author Website Setup service—your 24/7 digital storefront, resume, portfolio, and brand hub.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.author-website-setup.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">\n                          Having a personal website means readers, bookstores, and media can learn about you anytime, anywhere. We handle creative design, content layout, and technical setup from start to finish.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Website Packages & Structure:\n                          </h6>\n                          <div class=\"row g-3 mb-3\">\n                            <div class=\"col-md-4\">\n                              <div class=\"p-2.5 rounded-2 h-100\" style=\"background: #ffffff; border: 1px solid #ebd9c4;\">\n                                <strong class=\"d-block mb-1\" style=\"color: #2b2219; font-size: 0.92rem;\">3-Page Setup</strong>\n                                <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.84rem; line-height: 1.55;\">\n                                  <li class=\"editable-field\" data-block-key=\"service.author-website-setup.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">Up to 3 custom pages</li>\n                                  <li class=\"editable-field\" data-block-key=\"service.author-website-setup.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">2 featured book images</li>\n                                  <li class=\"editable-field\" data-block-key=\"service.author-website-setup.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">1 dedicated email account</li>\n                                  <li class=\"editable-field\" data-block-key=\"service.author-website-setup.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">Contact form integration</li>\n                                </ul>\n                              </div>\n                            </div>\n                            <div class=\"col-md-4\">\n                              <div class=\"p-2.5 rounded-2 h-100\" style=\"background: #ffffff; border: 1px solid #ebd9c4;\">\n                                <strong class=\"d-block mb-1\" style=\"color: #2b2219; font-size: 0.92rem;\">6-Page Setup</strong>\n                                <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.84rem; line-height: 1.55;\">\n                                  <li class=\"editable-field\" data-block-key=\"service.author-website-setup.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">Up to 6 custom pages</li>\n                                  <li class=\"editable-field\" data-block-key=\"service.author-website-setup.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">10 featured book images</li>\n                                  <li class=\"editable-field\" data-block-key=\"service.author-website-setup.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">2 rotating header banners</li>\n                                  <li class=\"editable-field\" data-block-key=\"service.author-website-setup.li8\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">2 dedicated email accounts</li>\n                                </ul>\n                              </div>\n                            </div>\n                            <div class=\"col-md-4\">\n                              <div class=\"p-2.5 rounded-2 h-100\" style=\"background: #ffffff; border: 1px solid #ebd9c4;\">\n                                <strong class=\"d-block mb-1\" style=\"color: #2b2219; font-size: 0.92rem;\">10-Page Setup</strong>\n                                <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.84rem; line-height: 1.55;\">\n                                  <li class=\"editable-field\" data-block-key=\"service.author-website-setup.li9\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">Up to 10 custom pages</li>\n                                  <li class=\"editable-field\" data-block-key=\"service.author-website-setup.li10\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">Up to 60 MB asset storage</li>\n                                  <li class=\"editable-field\" data-block-key=\"service.author-website-setup.li11\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">4 rotating header banners</li>\n                                  <li class=\"editable-field\" data-block-key=\"service.author-website-setup.li12\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">3 dedicated email accounts</li>\n                                  <li class=\"editable-field\" data-block-key=\"service.author-website-setup.li13\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">Animated book excerpt area</li>\n                                </ul>\n                              </div>\n                            </div>\n                          </div>\n\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.94rem;\">\n                            Flexible Page Choices Available:\n                          </h6>\n                          <p class=\"mb-2 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.6;\" data-block-key=\"service.author-website-setup.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">\n                            Home, About the Book, About the Author, Order / Retailer Links, Excerpt, Contact Page, Reviews & Media, Events, and Photo Gallery.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.author-website-setup.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-website-setup', this)\">\n                            <em>*Free Domain & Hosting: Custom domain name registration and high-speed web hosting are included completely free for an entire year.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "press-release-essential-edition": "<div class=\"press-release-essential-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.press-release-essential-edition.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('press-release-essential-edition', this)\">\n                          When done right, a press release is an effective way to get publicity. Grab the media’s attention and create widespread exposure for your title with an expertly crafted news release.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.press-release-essential-edition.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('press-release-essential-edition', this)\">\n                          The Omni Press Release – Essential Edition helps you grab the media’s attention by promoting your book with an expertly crafted press release. Prepared in a format to pique editors' interest in your book, your press release is delivered to numerous media outlets, creating the potential for increased coverage of you and your book. More coverage equals more exposure for your title.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            The Press Release – Essential Edition Includes:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.press-release-essential-edition.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('press-release-essential-edition', this)\">\n                              <strong>Customized One-Page Press Release:</strong> Expertly crafted by a professional writer based on the detailed information and story background you provide about your book.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.press-release-essential-edition.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('press-release-essential-edition', this)\">\n                              <strong>Targeted Distribution to 500+ Media Outlets:</strong> Delivery of your press release to a minimum of 500 media outlets chosen strategically based on location, book genre, target audience, and subject matter; recipients may include magazines, newspapers, online publications, and radio and TV programs.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.press-release-essential-edition.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('press-release-essential-edition', this)\">\n                              <strong>One-Month Comprehensive PR Tracking via Meltwater:</strong> Active tracking for one month through Meltwater's industry-leading PR monitoring platform to monitor pickups and news clips.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #ad7d42; font-size: 0.95rem;\">\n                            About Meltwater\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.press-release-essential-edition.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('press-release-essential-edition', this)\">\n                            Meltwater was founded in 2001 as the world’s first online media monitoring company. Today, Meltwater is a global leader in media intelligence and social analytics, helping to bridge the gap between Public Relations, Communications, and Marketing departments with an intuitive, all-in-one solution powered by AI-driven insights. Over 30,000 of the world’s most respected brands rely on Meltwater across more than 55 offices on six continents.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Note: </span>\n                          <span style=\"color: #57534e; font-size: 0.88rem;\">\n                            Press release samples and distribution recommendations are provided during your campaign consultation.\n                          </span>\n                        </div>\n                      </div>\n                    </div>",
  "press-release-web-optimized-edition": "<div class=\"press-release-web-optimized-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.press-release-web-optimized-edition.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('press-release-web-optimized-edition', this)\">\n                          With a web-optimized press release, anyone who conducts a web search of you or your book can find you much easier, including members of the press searching for story ideas.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.press-release-web-optimized-edition.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('press-release-web-optimized-edition', this)\">\n                          The Omni Press Release – Web-Optimized Edition is professionally crafted to include strategic search keywords that increase your release’s chances of being returned as a higher ranking search engine result. The easier your release is to find, the more likely you are to get promotional coverage and online discoverability for your book.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Press Release – Web-Optimized Edition Includes:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.press-release-web-optimized-edition.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('press-release-web-optimized-edition', this)\">\n                              <strong>Keyword-Optimized Professional Writing:</strong> A professional writer crafts your press release and infuses strategic keywords to optimize it for search engine results, so your release has the highest probability of being found and read.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.press-release-web-optimized-edition.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('press-release-web-optimized-edition', this)\">\n                              <strong>Newswire Distribution via PRWeb:</strong> Distributed to as many as 30,000 opt-in journalists and more than 250,000 news subscribers through our newswire service partner, PRWeb. Distributed releases commonly appear on prominent news hubs including Google News, Yahoo News, and websites where journalists search daily for relevant news and topics.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.press-release-web-optimized-edition.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('press-release-web-optimized-edition', this)\">\n                              <strong>One-Month Press Release Tracking:</strong> Active monitoring for 30 days to measure digital pickups, indexing, and syndication across the web.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.press-release-web-optimized-edition.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('press-release-web-optimized-edition', this)\">\n                              <strong>Activity Feedback & Performance Reporting:</strong> Comprehensive activity feedback and analytics so you can track the reach, reads, clicks, and overall effectiveness of your web-optimized release.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Note: </span>\n                          <span style=\"color: #57534e; font-size: 0.88rem;\">\n                            Web-optimized press release samples and keyword strategy recommendations are available upon request.\n                          </span>\n                        </div>\n                      </div>\n                    </div>",
  "radio-book-talk": "<div class=\"radio-book-talk-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.radio-book-talk.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('radio-book-talk', this)\">\n                          Talk about what you love and introduce your book to listeners nationwide. Combine terrestrial radio reach with prominent bookish podcast features on America Tonight, Books on Air, and Newsgram.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.radio-book-talk.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('radio-book-talk', this)\">\n                          You'll never run out of places to talk about books. There are cafés, libraries, bookstores, and you can chat about it on the radio. As an author, you can use the airwaves not only to talk about what you love, but to promote your book to interested listeners across the country.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.radio-book-talk.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('radio-book-talk', this)\">\n                          With our Radio Book Talk service, you get both online and terrestrial radio coverage: talk about your book on a radio show hosted by Kate Delaney, an Emmy award-winning broadcaster, and get interviewed on WebTalkRadio’s Books on Air. Plus, your book will be announced to the avid listeners of Newsgram, a show that highlights trends and popular recommendations.\n                        </p>\n\n                        <div class=\"p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.88rem;\" data-block-key=\"service.radio-book-talk.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('radio-book-talk', this)\">\n                            <strong>Genre Recommendation:</strong> Radio Book Talk is highly recommended for literary novels, memoirs, business books, and nonfiction titles such as self-help and personal growth.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Radio Book Talk Package Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.radio-book-talk.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('radio-book-talk', this)\">\n                              <strong>8 to 12-Minute Interview on America Tonight:</strong> In-depth interview with Emmy Award-winning host Kate Delaney. America Tonight airs across approximately 100 stations nationwide and reaches around 2.9 million listeners. You will receive an MP3 audio file following the interview.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.radio-book-talk.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('radio-book-talk', this)\">\n                              <strong>15-Minute Online Interview on Books on Air:</strong> Featured with host Suzanne Harris on WebTalkRadio, and syndicated across Apple Podcasts, iHeartRadio, Spotify, and major podcast aggregators.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.radio-book-talk.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('radio-book-talk', this)\">\n                              <strong>Book Feature on Newsgram:</strong> Featured spotlight on WebTalkRadio's Newsgram show hosted by seasoned newsroom personality Sam Youmans, distributed across Apple, iHeartRadio, and Spotify.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.radio-book-talk.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('radio-book-talk', this)\">\n                              <strong>Digital Master Copies:</strong> Digital copies of all radio interviews with full commercial rights for your author website, social media promotions, speaking engagements, and press kits.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #ad7d42; font-size: 0.95rem;\">\n                            About the Hosts & Broadcasters\n                          </h6>\n                          <div class=\"d-flex flex-column gap-2\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.6;\">\n                            <p class=\"mb-0 editable-field\" data-block-key=\"service.radio-book-talk.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('radio-book-talk', this)\">\n                              <strong>Kate Delaney:</strong> An award-winning and respected national broadcaster with 20 years in television and radio, having interviewed over 16,000 guests. She garnered a Television Emmy for her special report on the AIDS epidemic and several Golden Mics for her investigative series.\n                            </p>\n                            <p class=\"mb-0 editable-field\" data-block-key=\"service.radio-book-talk.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('radio-book-talk', this)\">\n                              <strong>Suzanne Harris (Books on Air):</strong> An experienced media personality who guides authors in sharing their creative journey with passionate readers worldwide.\n                            </p>\n                            <p class=\"mb-0 editable-field\" data-block-key=\"service.radio-book-talk.p7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('radio-book-talk', this)\">\n                              <strong>Sam Youmans (Newsgram):</strong> A seasoned newsroom veteran who curates standout book releases and creative work for dedicated weekly listeners.\n                            </p>\n                          </div>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Broadcast Policy: </span>\n                          <span style=\"color: #57534e; font-size: 0.88rem;\">\n                            Featured books are subject to network review and approval. Certain themes, genres, or explicit topics may not be suitable for terrestrial broadcast syndication.\n                          </span>\n                        </div>\n                      </div>\n                    </div>",
  "audio-snip": "<div class=\"audio-snip-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.audio-snip.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('audio-snip', this)\">\n                          Thirty seconds may seem like an insignificant amount of time, but in half a minute you can grab reader attention, present your hook, and direct listeners right to where your book is sold.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.audio-snip.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('audio-snip', this)\">\n                          Yes, you read that right—it's entirely possible to reach out to prospective readers in such a short window. All you need is the right marketing vehicle. The Audio Snip service serves as a high-impact audio trailer of your book to announce its release, create intrigue, and inform listeners where they can purchase their copy.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.audio-snip.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('audio-snip', this)\">\n                          With this service, you take your story directly to the airwaves and digital audio channels with a professionally voiced and engineered audio teaser designed to integrate seamlessly into your author platform.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            The Audio Snip Package Includes:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.audio-snip.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('audio-snip', this)\">\n                              <strong>30-Second Professionally Produced Audio Commercial:</strong> Crisp, studio-engineered audio teaser highlighting your book title, logline, author identity, and retail availability.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.audio-snip.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('audio-snip', this)\">\n                              <strong>Studio Voiceover & Sound Design:</strong> Professional voice talent and licensed background music tuned to match your book's mood and genre.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.audio-snip.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('audio-snip', this)\">\n                              <strong>Multi-Platform Digital Asset:</strong> Complete digital master copy formatted for radio rotation, podcast preroll/midroll ads, Instagram reels, YouTube shorts, and author website landing pages.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.audio-snip.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('audio-snip', this)\">\n                            <em>*Tip: An Audio Snip is an ideal promotional companion to pair with social media advertising, website header media, and newsletter releases.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "online-interview": "<div class=\"online-interview-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.online-interview.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-interview', this)\">\n                          Position yourself as an expert on your book’s subject matter and put your voice on the radio. Gain a powerful promotional push and an evergreen audio asset with broadcast veteran J. Douglas Barker.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.online-interview.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-interview', this)\">\n                          Position yourself as an authority in your genre and share the heart of your message with eager listeners. The Online Interview service is a strategic marketing tool designed to enhance your promotional plan. With the rise in streaming audio and satellite radio, listeners have more choices and more ways to access content than ever before, and streaming radio is an exceptional way to reach new audiences.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.online-interview.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-interview', this)\">\n                          Plus, you can use your high-quality recorded interview as a launch pad for your next big promotional push across social media, author blogs, and speaking engagements.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Online Interview Package Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.online-interview.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-interview', this)\">\n                              <strong>10- to 15-Minute Online Radio Interview:</strong> Recorded comfortably over the phone, focused on your book, writing process, and expertise.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.online-interview.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-interview', this)\">\n                              <strong>Broadcast on Omni Radio Stations:</strong>\n                              <ul class=\"mt-1 mb-1 ps-3\" style=\"font-size: 0.88rem;\">\n                                <li><strong>Omni Radio:</strong> Airs Saturdays at 3:00 p.m. CT (encore Thursdays at 11:00 p.m. CT)</li>\n                                <li class=\"editable-field\" data-block-key=\"service.online-interview.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-interview', this)\"><strong>Omni Radio 2:</strong> Airs Saturdays at 1:00 p.m. CT (encore Sundays at 1:00 p.m. CT)</li>\n                              </ul>\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.online-interview.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-interview', this)\">\n                              <strong>Global Syndication:</strong> Syndicated via iTunes and Toginet.com, digitally retrievable for on-demand playback on mobile devices (iPhone, iPad, Android).\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.online-interview.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-interview', this)\">\n                              <strong>Master Digital Audio Copy:</strong> Unlimited rights to burn, distribute, play at speaking engagements, or embed on your author website, blog, and email promotions.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.online-interview.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-interview', this)\">\n                              <strong>Pre-Show Questionnaire & Guided Warm-Up:</strong> A thorough pre-show questionnaire and warm-up conversation with host J. Douglas Barker to ensure you are confident and comfortable with the interview topics.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #ad7d42; font-size: 0.95rem;\">\n                            About Host J. Douglas Barker\n                          </h6>\n                          <p class=\"mb-2 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.online-interview.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-interview', this)\">\n                            With a passion for all things creative, J. Douglas Barker is an accomplished actor, singer, and audio producer with over 35 years of studio excellence. He can be heard worldwide as producer and talent for Toginet Radio Network, with voice actor credits in the CBS \"Movie of the Week,\" along with commercial and studio work for national accounts including Disney, Church's Chicken, and United Technologies.\n                          </p>\n                          <p class=\"fst-italic mb-0 editable-field\" style=\"color: #78716c; font-size: 0.86rem;\" data-block-key=\"service.online-interview.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('online-interview', this)\">\n                            Never been interviewed for radio before? No problem. The interview is structured to be fun, relaxing, and collaborative. J. Douglas Barker guides you through every step so you shine on the airwaves.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "set-your-own-price": "<div class=\"set-your-own-price-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.set-your-own-price.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                          Take control of your book's retail price and the royalties you earn. Set Your Own Price gives you the flexibility to adjust the retail price of the hardcover and paperback formats of your book.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.set-your-own-price.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                          Pricing is a fundamental component of book marketing. Whether your objective is to set an enticing promotional price to drive maximum unit sales or to establish a premium price point that yields higher royalties per copy, the Set Your Own Price service puts you in the driver’s seat.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Key Benefits & Strategic Power:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.set-your-own-price.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                              <strong>Format Flexibility:</strong> Adjust the retail price of both hardcover and paperback editions of your title.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.set-your-own-price.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                              <strong>Strategic Pricing Alignment:</strong> Position your title competitively within your genre against competing commercial releases.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.set-your-own-price.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                              <strong>Synergy with Author Advantage:</strong> Combine with the Author Advantage Royalty Program to set a competitive retail price while harvesting maximum royalty margins.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.set-your-own-price.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                              <strong>Full Distribution Synchronization:</strong> Price updates are distributed across major online booksellers and global distributor networks including Amazon, Barnes & Noble, and Ingram.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.set-your-own-price.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                            <em>*Consultation Note: Contact your Publishing Consultant to analyze print-on-demand base production costs and identify optimal price thresholds for your page count.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "author-advantage-royalty-program": "<div class=\"author-advantage-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.author-advantage-royalty-program.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-advantage-royalty-program', this)\">\n                          The Author Advantage Royalty Program empowers you to earn substantial financial gains with every print book sold. This 3-Year Program ensures you receive maximum profits and deeply discounted author copies.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.author-advantage-royalty-program.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-advantage-royalty-program', this)\">\n                          Figuring out how much your book will cost and how much you will receive from each sale is easy and transparent. The retail price is based on your final manuscript's page count, and your royalty is determined by clean, industry-leading payout percentages.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Royalty Calculations:\n                          </h6>\n                          <div class=\"d-flex flex-column gap-2\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.7;\">\n                            <div class=\"p-2.5 rounded-2\" style=\"background: #fff; border: 1px solid #e7ded5;\">\n                              <strong class=\"d-block text-dark\">Online Bookstore Sales:</strong>\n                              <span>Your Book’s List Price × <strong>60%</strong> = Your Royalty</span>\n                            </div>\n                            <div class=\"p-2.5 rounded-2\" style=\"background: #fff; border: 1px solid #e7ded5;\">\n                              <strong class=\"d-block text-dark\">Channel Retailers (Amazon, Barnes & Noble, etc.):</strong>\n                              <span>Your Book’s List Price × <strong>15%</strong> = Your Royalty</span>\n                            </div>\n                          </div>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #ad7d42; font-size: 0.95rem;\">\n                            Enrollment Start Dates:\n                          </h6>\n                          <p class=\"mb-2 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.author-advantage-royalty-program.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-advantage-royalty-program', this)\">\n                            The Work will be enrolled on the earlier of the following:\n                          </p>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\">\n                            <li class=\"editable-field\" data-block-key=\"service.author-advantage-royalty-program.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-advantage-royalty-program', this)\">\n                              <strong>Already available for sale:</strong> On the first day of the next calendar quarter following receipt by Company of both the signed Agreement and payment of the applicable fee.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.author-advantage-royalty-program.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-advantage-royalty-program', this)\">\n                              <strong>Not yet available for sale:</strong> On the first day of the next calendar quarter after the Work becomes available for sale, provided payment has been received prior to that time.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.author-advantage-royalty-program.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('author-advantage-royalty-program', this)\">\n                            <em>*Please Note: To be eligible for the Author Advantage Royalty Program, your publishing package must have been purchased on or after January 2023. Combining this program with Set Your Own Price enables maximum author earnings.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "retail-focus": "<div class=\"retail-focus-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.retail-focus.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus', this)\">\n                          If your dream is to see your work displayed on a bookstore shelf, Retail Focus provides direct pitching to 25 independent bookstores across the US, premier trade publication ads, and a 2-bookstore stocking test guarantee.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.retail-focus.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus', this)\">\n                          Although self-published titles are gaining popularity, authors often face hurdles getting brick-and-mortar stores to stock their books. Retailers consider factors like sales potential, subject matter, and returnability. The Retail Focus Service combines direct sales pitching with premier trade publication advertising to make your book stand out.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Retail Focus Package Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus', this)\">\n                              <strong>Direct Pitching to 25 Independent Bookstores:</strong> Pitched across the US (with focus on a specific area or state) over the span of 3 months using a customized sales kit.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus', this)\">\n                              <strong>Ingram Advance Catalog Ad:</strong> Single-slot print ad in Ingram’s Advance Catalog buying guide, read by over 7,000 print and 27,000 digital retailers, librarians, and international buyers.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus', this)\">\n                              <strong>ForeWord Magazine Ad:</strong> Single-slot print ad in the quarterly ForeWord Magazine, reaching more than 30,000 librarians and booksellers (including 1,100 ABA members).\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus', this)\">\n                              <strong>Booksellers Return Program for 12 Months:</strong> Full 1-year returnable status ensuring bookstores can stock your title risk-free.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus', this)\">\n                              <strong>Retailer Test Guarantee:</strong> A guarantee that at least two (2) bookstores or retailers will agree to test your book.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #ad7d42; font-size: 0.95rem;\">\n                            Program Guidelines & Prerequisites:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\">\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus', this)\">Option to extend your campaign by adding 25 more independent bookstores.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus', this)\">Retail-ready review: Complimentary cover enhancements may be recommended to meet bookstore standards; professional copyediting is advised.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus.li8\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus', this)\">Publication timeline: Official publication date must not be more than two (2) years ago, or the book must have received an award, 5-star review, or media recognition in the last 24 months.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus.li9\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus', this)\">Active retail availability: Your book must already be available for sale prior to campaign launch.</li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "retail-focus-for-childrens-books": "<div class=\"retail-focus-children-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.retail-focus-for-childrens-books.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus-for-childrens-books', this)\">\n                          Tailored specifically for children's literature, this service pitches your title to 25 independent bookstores, features your book in Children's Advance Catalog and ForeWord Magazine, and includes a 2-bookstore test guarantee.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.retail-focus-for-childrens-books.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus-for-childrens-books', this)\">\n                          Children’s books are perennially in demand, but children’s bookstore buyers have particular criteria regarding illustration quality, age grading, and subject matter. The Retail Focus for Children’s Books service is customized from the ground up to address what independent children’s book buyers look for.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Package Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus-for-childrens-books.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus-for-childrens-books', this)\">\n                              <strong>Direct Pitching to 25 Independent Bookstores:</strong> Pitched across the US (with focus on your target region or state) over 3 months using a tailored children's sales kit.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus-for-childrens-books.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus-for-childrens-books', this)\">\n                              <strong>Ingram Children's Advance Catalog Ad:</strong> Single-slot print ad in the dedicated bimonthly children's buying guide read by 7,000 print and 29,000 digital retailers and librarians.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus-for-childrens-books.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus-for-childrens-books', this)\">\n                              <strong>ForeWord Magazine Ad:</strong> Single-slot print ad reaching over 30,000 librarians and booksellers.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus-for-childrens-books.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus-for-childrens-books', this)\">\n                              <strong>Booksellers Return Program for 12 Months:</strong> 1 full year of returnable status eliminating retailer stocking risk.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus-for-childrens-books.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus-for-childrens-books', this)\">\n                              <strong>Retailer Test Guarantee:</strong> A guarantee that at least two (2) bookstores or retailers will agree to test your book.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #ad7d42; font-size: 0.95rem;\">\n                            Program Guidelines & Prerequisites:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\">\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus-for-childrens-books.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus-for-childrens-books', this)\">Option to extend your campaign to 25 additional independent bookstores.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus-for-childrens-books.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus-for-childrens-books', this)\">Complimentary cover adjustments may be provided by design professionals if needed to satisfy children's retailer expectations.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus-for-childrens-books.li8\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus-for-childrens-books', this)\">Book must be published within the last two (2) years or have received recent recognition (award, review, media coverage) within 24 months.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.retail-focus-for-childrens-books.li9\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retail-focus-for-childrens-books', this)\">Book must already be available for sale before the campaign launches.</li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "library-focus": "<div class=\"library-focus-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.library-focus.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('library-focus', this)\">\n                          Make your book available in public libraries across the United States. Omni pitches your title directly to Collection Development Departments and Acquisition Librarians of 25 public libraries, with ads in Forecast Catalog and ForeWord Magazine.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.library-focus.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('library-focus', this)\">\n                          Libraries are beloved sites of community, history, and education. Getting libraries to stock your book connects you directly to enthusiastic readers, book clubs, and students. The Library Focus Service pairs institutional trade advertising with direct acquisition pitching.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Library Focus Inclusions:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.library-focus.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('library-focus', this)\">\n                              <strong>Direct Pitching to 25 Public Libraries:</strong> Presented directly to Collection Development Departments and Acquisition Librarians across the US over 3 months using a customized sales kit.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.library-focus.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('library-focus', this)\">\n                              <strong>Baker & Taylor Forecast Catalog Ad:</strong> Single-slot print ad in the most widely circulated library buying publication, mailed to 45,000 librarians in the US.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.library-focus.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('library-focus', this)\">\n                              <strong>ForeWord Magazine Ad:</strong> Single-slot print ad reaching over 30,000 librarians and booksellers.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.library-focus.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('library-focus', this)\">\n                              <strong>Booksellers Return Program for 12 Months:</strong> Returnable status across wholesale distributors.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.library-focus.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('library-focus', this)\">\n                              <strong>Library Test Guarantee:</strong> A guarantee that at least two (2) libraries will agree to test your book.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #ad7d42; font-size: 0.95rem;\">\n                            Library Guidelines & Prerequisites:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\">\n                            <li class=\"editable-field\" data-block-key=\"service.library-focus.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('library-focus', this)\">Option to extend the campaign by pitching 25 additional public libraries.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.library-focus.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('library-focus', this)\">Complimentary cover design adjustments and copyediting recommendations to ensure your book is library-ready.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.library-focus.li8\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('library-focus', this)\">Official publication date must not be more than two (2) years ago, or the book must have received recent recognition (awards, reviews, press) in the last 24 months.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.library-focus.li9\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('library-focus', this)\">Title must already be live and available for sale before the campaign starts.</li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "booksellers-return-program": "<div class=\"booksellers-return-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.booksellers-return-program.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('booksellers-return-program', this)\">\n                          The ability to return unsold books is a standard publishing practice since the Great Depression. Designate your book as \"Returnable\" in Ingram ipage and Baker & Taylor systems for 12 months with no royalty chargebacks.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.booksellers-return-program.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('booksellers-return-program', this)\">\n                          Often, booksellers will hesitate to order and stock books when they aren’t “Returnable.” Booksellers mitigate their own financial risk by relying on publishers to credit returned copies. If getting your title stocked on bookstore shelves or booking in-store book signings is part of your marketing plan, the Booksellers Return Program is an essential element to earning shelf space.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            When You Enroll in the Booksellers Return Program:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.booksellers-return-program.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('booksellers-return-program', this)\">\n                              <strong>Designated \"Returnable\" in Ingram's ipage:</strong> Visible to retailers and libraries worldwide through the world's largest wholesaler and distributor of books.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.booksellers-return-program.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('booksellers-return-program', this)\">\n                              <strong>Designated \"Returnable\" in Baker & Taylor:</strong> Listed in the ordering system of a leading book distributor with over 180 years of industry leadership.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.booksellers-return-program.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('booksellers-return-program', this)\">\n                              <strong>No Royalty Chargebacks:</strong> You will not be charged back for royalties earned on sales to stores if copies are returned.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.booksellers-return-program.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('booksellers-return-program', this)\">\n                              <strong>One-Year Protection:</strong> Valid for one full year (12 months) from the date your book goes live.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.booksellers-return-program.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('booksellers-return-program', this)\">\n                            <em>*Timeline: Your book will be designated on ipage within two to seven weeks. It can then take 30 to 60 days for returnability status to appear within individual retailers’ systems. Confirmation of your title's listing in ipage is available upon request.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "booksellers-return-program-renewal": "<div class=\"booksellers-return-renewal-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.booksellers-return-program-renewal.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('booksellers-return-program-renewal', this)\">\n                          Renew your book’s participation in the Booksellers Return Program for one year. Keep your book \"Returnable\" in distributor ordering systems so retailers continue stocking and re-ordering without risk.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.booksellers-return-program-renewal.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('booksellers-return-program-renewal', this)\">\n                          When you purchase this program renewal, your book will remain “Returnable” in major book distributor ordering systems (Ingram and Baker & Taylor), reassuring bookstores that they can return any unsold copies without loss of profit.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.booksellers-return-program-renewal.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('booksellers-return-program-renewal', this)\">\n                          Renew your valuable Booksellers Return Program for another year and help your title continue to meet commercial bookseller standards for physical retail stocking and in-store events.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Renewal Highlights:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.booksellers-return-program-renewal.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('booksellers-return-program-renewal', this)\">\n                              <strong>Uninterrupted Listing:</strong> Seamlessly maintains active \"Returnable\" status in Ingram and Baker & Taylor catalogs without lapse.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.booksellers-return-program-renewal.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('booksellers-return-program-renewal', this)\">\n                              <strong>No Royalty Chargebacks:</strong> Retains complete protection against royalty deductions for returned retail inventory.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.booksellers-return-program-renewal.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('booksellers-return-program-renewal', this)\">\n                              <strong>Annual Increment Flexibility:</strong> Valid for one full year and renewable annually to match your long-term promotional campaign.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>"
  };

